            return new ResponseEntity<Set<User>>(groupUsersSet, HttpStatus.OK);
        } catch (Exception e) {
            logger.error("Error finding group with id " + groupId + ": "
                + e.getMessage());
            return new ResponseEntity<Set<User>>(HttpStatus.NOT_FOUND);
        }
    }
}
