    public int hashCode() {
        // two randomly chosen prime numbers
        return new HashCodeBuilder(19, 53).
            appendSuper(super.hashCode()).
            append(getFirstName()).
            append(getLastName()).
            append(getEmail()).
            append(getBirthday()).
            append(getLanguage()).
            toHashCode();
    }

    /**
