//! Helpers that reproduce how the Java original (Jackson, BeanUtils, Java
//! `toString`, the `PropertyValueConverter`) reads and writes values.

use serde_json::{Map, Value};

/// A Jackson-style deserialisation failure (an `IOException` in the original).
#[derive(Debug)]
pub struct JErr(pub String);

pub type JResult<T> = Result<T, JErr>;

pub fn jerr<T>(msg: impl Into<String>) -> JResult<T> {
    Err(JErr(msg.into()))
}

/// Jackson `String` property: scalars are accepted, containers are not.
pub fn j_string(v: &Value) -> JResult<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(s.clone())),
        Value::Bool(b) => Ok(Some(b.to_string())),
        Value::Number(n) => Ok(Some(n.to_string())),
        _ => jerr("cannot deserialize a String from a container"),
    }
}

/// Jackson `Integer` property (wrapper): null stays null.
pub fn j_int(v: &Value) -> JResult<Option<i32>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i32::try_from(i).map(Some).or_else(|_| jerr("int out of range"))
            } else if let Some(f) = n.as_f64() {
                // ACCEPT_FLOAT_AS_INT: truncate towards zero
                if f.is_finite() && f >= i32::MIN as f64 && f <= i32::MAX as f64 {
                    Ok(Some(f.trunc() as i32))
                } else {
                    jerr("int out of range")
                }
            } else {
                jerr("bad number")
            }
        }
        Value::String(s) => match s.trim().parse::<i32>() {
            Ok(i) => Ok(Some(i)),
            Err(_) => jerr("cannot parse int"),
        },
        _ => jerr("cannot deserialize an int"),
    }
}

/// Jackson `int` property (primitive): null becomes 0.
pub fn j_int_prim(v: &Value) -> JResult<i32> {
    Ok(j_int(v)?.unwrap_or(0))
}

/// Jackson `Boolean` property (wrapper).
pub fn j_bool(v: &Value) -> JResult<Option<bool>> {
    match v {
        Value::Null => Ok(None),
        Value::Bool(b) => Ok(Some(*b)),
        Value::Number(n) => match n.as_i64() {
            Some(i) => Ok(Some(i != 0)),
            None => jerr("cannot deserialize a boolean from a float"),
        },
        Value::String(s) => match s.trim() {
            "true" | "True" | "TRUE" => Ok(Some(true)),
            "false" | "False" | "FALSE" => Ok(Some(false)),
            "" => Ok(None),
            _ => jerr("cannot parse boolean"),
        },
        _ => jerr("cannot deserialize a boolean"),
    }
}

/// Jackson `boolean` property (primitive): null becomes false.
pub fn j_bool_prim(v: &Value) -> JResult<bool> {
    Ok(j_bool(v)?.unwrap_or(false))
}

/// Jackson `Double` property (wrapper).
pub fn j_f64(v: &Value) -> JResult<Option<f64>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => Ok(n.as_f64()),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return Ok(None);
            }
            match t.parse::<f64>() {
                Ok(f) => Ok(Some(f)),
                Err(_) => jerr("cannot parse double"),
            }
        }
        _ => jerr("cannot deserialize a double"),
    }
}

/// Jackson `double` property (primitive): null becomes 0.0.
pub fn j_f64_prim(v: &Value) -> JResult<f64> {
    Ok(j_f64(v)?.unwrap_or(0.0))
}

/// `java.time.LocalDate` (ISO `yyyy-MM-dd` string or `[y, m, d]` array).
pub fn j_date(v: &Value) -> JResult<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => {
            if valid_iso_date(s) {
                Ok(Some(s.clone()))
            } else {
                jerr("cannot parse LocalDate")
            }
        }
        Value::Array(a) if a.len() == 3 => {
            let y = a[0].as_i64();
            let m = a[1].as_i64();
            let d = a[2].as_i64();
            match (y, m, d) {
                (Some(y), Some(m), Some(d)) => {
                    let s = format!("{:04}-{:02}-{:02}", y, m, d);
                    if valid_iso_date(&s) {
                        Ok(Some(s))
                    } else {
                        jerr("cannot parse LocalDate")
                    }
                }
                _ => jerr("cannot parse LocalDate"),
            }
        }
        _ => jerr("cannot deserialize a LocalDate"),
    }
}

fn valid_iso_date(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return false;
    }
    let num = |r: std::ops::Range<usize>| -> Option<u32> {
        let t = &s[r];
        if t.bytes().all(|c| c.is_ascii_digit()) {
            t.parse().ok()
        } else {
            None
        }
    };
    let (y, m, d) = match (num(0..4), num(5..7), num(8..10)) {
        (Some(y), Some(m), Some(d)) => (y, m, d),
        _ => return false,
    };
    if !(1..=12).contains(&m) || d == 0 {
        return false;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let dim = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        _ => {
            if leap {
                29
            } else {
                28
            }
        }
    };
    d <= dim
}

/// `java.util.Locale` (string such as `en` or `de_DE`), stored as `Locale.toString()`.
pub fn j_locale(v: &Value) -> JResult<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => {
            let mut parts = s.splitn(3, '_');
            let lang = parts.next().unwrap_or("").to_lowercase();
            let country = parts.next().map(|c| c.to_uppercase());
            let variant = parts.next();
            let mut out = lang;
            if let Some(c) = country {
                out.push('_');
                out.push_str(&c);
            }
            if let Some(var) = variant {
                if out.len() == 2 || out.contains('_') {
                    out.push('_');
                }
                out.push_str(var);
            }
            Ok(Some(out))
        }
        _ => jerr("cannot deserialize a Locale"),
    }
}

/// Jackson `List<String>` / `List<Double>` style containers (null elements allowed).
pub fn j_list<T>(v: &Value, f: impl Fn(&Value) -> JResult<Option<T>>) -> JResult<Option<Vec<Option<T>>>> {
    match v {
        Value::Null => Ok(None),
        Value::Array(a) => {
            let mut out = Vec::with_capacity(a.len());
            for e in a {
                out.push(f(e)?);
            }
            Ok(Some(out))
        }
        _ => jerr("cannot deserialize a list"),
    }
}

pub fn j_object(v: &Value) -> JResult<&Map<String, Value>> {
    match v.as_object() {
        Some(o) => Ok(o),
        None => jerr("expected an object"),
    }
}

/// `JsonNode.asInt()` as used for the PUT `id` check.
pub fn as_int_lenient(v: &Value) -> i32 {
    match v {
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i as i32
            } else {
                n.as_f64().map(|f| f as i32).unwrap_or(0)
            }
        }
        Value::String(s) => s.trim().parse::<i32>().unwrap_or(0),
        Value::Bool(b) => i32::from(*b),
        _ => 0,
    }
}

/// BeanUtils `ConvertUtils.convert(String, Integer.class)`: invalid input becomes 0.
pub fn conv_int(s: &str) -> i32 {
    s.trim().parse::<i32>().unwrap_or(0)
}

/// BeanUtils `ConvertUtils.convert(String, Double.class)`: invalid input becomes 0.0.
pub fn conv_f64(s: &str) -> f64 {
    s.trim().parse::<f64>().unwrap_or(0.0)
}

/// BeanUtils `ConvertUtils.convert(String, Boolean.class)`: invalid input becomes false.
pub fn conv_bool(s: &str) -> bool {
    matches!(
        s.trim().to_lowercase().as_str(),
        "true" | "yes" | "y" | "on" | "1"
    )
}

/// Java `Double.toString(double)`.
pub fn java_double(d: f64) -> String {
    if d.is_nan() {
        return "NaN".into();
    }
    if d.is_infinite() {
        return if d > 0.0 { "Infinity".into() } else { "-Infinity".into() };
    }
    if d == 0.0 {
        return if d.is_sign_negative() { "-0.0".into() } else { "0.0".into() };
    }
    let abs = d.abs();
    let sign = if d < 0.0 { "-" } else { "" };
    if (1e-3..1e7).contains(&abs) {
        let mut s = format!("{}", abs);
        if !s.contains('.') {
            s.push_str(".0");
        }
        format!("{}{}", sign, s)
    } else {
        let sci = format!("{:e}", abs); // e.g. "1.2345e-5", "1e7"
        let (mant, exp) = sci.split_once('e').unwrap_or((&sci, "0"));
        let (first, rest) = match mant.split_once('.') {
            Some((a, b)) => (a.to_string(), b.to_string()),
            None => (mant.to_string(), String::new()),
        };
        let rest = if rest.is_empty() { "0".to_string() } else { rest };
        format!("{}{}.{}E{}", sign, first, rest, exp)
    }
}

/// `java.lang.Object.toString()` of a value deserialised by Jackson into `Object`.
/// Returns `None` for a null (Java would throw in the converter).
pub fn java_to_string(v: &Value) -> Option<String> {
    match v {
        Value::Null => None,
        Value::String(s) => Some(s.clone()),
        Value::Bool(b) => Some(b.to_string()),
        Value::Number(n) => Some(java_number(n)),
        other => Some(java_nested(other)),
    }
}

fn java_number(n: &serde_json::Number) -> String {
    if let Some(i) = n.as_i64() {
        i.to_string()
    } else if let Some(u) = n.as_u64() {
        u.to_string()
    } else {
        java_double(n.as_f64().unwrap_or(0.0))
    }
}

fn java_nested(v: &Value) -> String {
    match v {
        Value::Null => "null".into(),
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => java_number(n),
        Value::Array(a) => {
            let parts: Vec<String> = a.iter().map(java_nested).collect();
            format!("[{}]", parts.join(", "))
        }
        Value::Object(o) => {
            let parts: Vec<String> = o
                .iter()
                .map(|(k, v)| format!("{}={}", k, java_nested(v)))
                .collect();
            format!("{{{}}}", parts.join(", "))
        }
    }
}

/// `PropertyValueConverter.convertToEntityAttribute`: typed read-back of a stored string.
pub fn prop_from_db(s: &str) -> Value {
    if s.eq_ignore_ascii_case("true") {
        return Value::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return Value::Bool(false);
    }
    if commons_is_parsable(s) {
        let digits_only = |t: &str| !t.is_empty() && t.chars().all(|c| c.is_ascii_digit());
        if digits_only(s) || (s.starts_with('-') && digits_only(&s[1..])) {
            if let Ok(i) = s.parse::<i64>() {
                return Value::from(i);
            }
            return serde_json::Number::from_f64(s.parse::<f64>().unwrap_or(0.0))
                .map(Value::Number)
                .unwrap_or(Value::Null);
        }
        return match s.parse::<f64>() {
            Ok(f) => serde_json::Number::from_f64(f)
                .map(Value::Number)
                .unwrap_or(Value::Null),
            Err(_) => Value::String(s.to_string()),
        };
    }
    Value::String(s.to_string())
}

/// `org.apache.commons.lang3.math.NumberUtils.isParsable` (3.x semantics).
fn commons_is_parsable(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    if s.ends_with('.') {
        return false;
    }
    let body = if let Some(rest) = s.strip_prefix('-') {
        if rest.is_empty() {
            return false;
        }
        rest
    } else {
        s
    };
    let mut dots = 0;
    for c in body.chars() {
        if c == '.' {
            dots += 1;
            if dots > 1 {
                return false;
            }
        } else if !c.is_ascii_digit() {
            return false;
        }
    }
    true
}

/// Parses a JSON document and returns its first value (Jackson ignores trailing tokens).
pub fn parse_first(body: &[u8]) -> Result<Value, serde_json::Error> {
    let mut de = serde_json::Deserializer::from_slice(body);
    Value::deserialize_first(&mut de)
}

trait DeserializeFirst {
    fn deserialize_first(de: &mut serde_json::Deserializer<serde_json::de::SliceRead<'_>>)
        -> Result<Value, serde_json::Error>;
}

impl DeserializeFirst for Value {
    fn deserialize_first(
        de: &mut serde_json::Deserializer<serde_json::de::SliceRead<'_>>,
    ) -> Result<Value, serde_json::Error> {
        use serde::Deserialize;
        Value::deserialize(de)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn java_double_format() {
        assert_eq!(java_double(1.0), "1.0");
        assert_eq!(java_double(0.5), "0.5");
        assert_eq!(java_double(1e7), "1.0E7");
        assert_eq!(java_double(1.5e-5), "1.5E-5");
        assert_eq!(java_double(20026376.39), "2.002637639E7");
        assert_eq!(java_double(-3.0), "-3.0");
    }

    #[test]
    fn props_roundtrip_types() {
        assert_eq!(prop_from_db("12"), Value::from(12));
        assert_eq!(prop_from_db("-3"), Value::from(-3));
        assert_eq!(prop_from_db("true"), Value::Bool(true));
        assert_eq!(prop_from_db("x y"), Value::String("x y".into()));
        assert_eq!(prop_from_db("1.5"), serde_json::json!(1.5));
        assert_eq!(prop_from_db("1.0E10"), Value::String("1.0E10".into()));
        assert_eq!(prop_from_db("1."), Value::String("1.".into()));
    }

    #[test]
    fn conversions() {
        assert_eq!(conv_int("abc"), 0);
        assert_eq!(conv_int("4.0"), 0);
        assert_eq!(conv_int(" 7 "), 7);
        assert!(conv_bool("yes"));
        assert!(!conv_bool("maybe"));
        assert_eq!(conv_f64("abc"), 0.0);
    }

    #[test]
    fn dates() {
        assert!(valid_iso_date("1990-05-17"));
        assert!(!valid_iso_date("1990-02-30"));
        assert!(!valid_iso_date("notadate"));
    }
}

