//! Helpers that reproduce how the Java original (Jackson, BeanUtils, Java
//! `toString`, the `PropertyValueConverter`) reads and writes values.

use serde_json::{Map, Value};

/// A Jackson-style deserialisation failure (an `IOException` in the original).
#[derive(Debug)]
pub struct JErr(pub String);

pub type JResult<T> = Result<T, JErr>;

pub fn jerr<T>(msg: impl Into<String>) -> JResult<T> {
    Err(JErr(msg.into()))
}

/// Jackson `String` property: scalars are accepted, containers are not.
pub fn j_string(v: &Value) -> JResult<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(s.clone())),
        Value::Bool(b) => Ok(Some(b.to_string())),
        Value::Number(n) => Ok(Some(n.to_string())),
        _ => jerr("cannot deserialize a String from a container"),
    }
}

/// Jackson `Integer` property (wrapper): null stays null.
pub fn j_int(v: &Value) -> JResult<Option<i32>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i32::try_from(i).map(Some).or_else(|_| jerr("int out of range"))
            } else if let Some(f) = n.as_f64() {
                // ACCEPT_FLOAT_AS_INT: truncate towards zero
                if f.is_finite() && f >= i32::MIN as f64 && f <= i32::MAX as f64 {
                    Ok(Some(f.trunc() as i32))
                } else {
                    jerr("int out of range")
                }
            } else {
                jerr("bad number")
            }
        }
        Value::String(s) => match s.trim().parse::<i32>() {
            Ok(i) => Ok(Some(i)),
            Err(_) => jerr("cannot parse int"),
        },
        _ => jerr("cannot deserialize an int"),
    }
}

/// Jackson `int` property (primitive): null becomes 0.
pub fn j_int_prim(v: &Value) -> JResult<i32> {
    Ok(j_int(v)?.unwrap_or(0))
}

/// Jackson `Boolean` property (wrapper).
pub fn j_bool(v: &Value) -> JResult<Option<bool>> {
    match v {
        Value::Null => Ok(None),
        Value::Bool(b) => Ok(Some(*b)),
        Value::Number(n) => match n.as_i64() {
            Some(i) => Ok(Some(i != 0)),
            None => jerr("cannot deserialize a boolean from a float"),
        },
        Value::String(s) => match s.trim() {
            "true" | "True" | "TRUE" => Ok(Some(true)),
            "false" | "False" | "FALSE" => Ok(Some(false)),
            "" => Ok(None),
            _ => jerr("cannot parse boolean"),
        },
        _ => jerr("cannot deserialize a boolean"),
    }
}

/// Jackson `boolean` property (primitive): null becomes false.
pub fn j_bool_prim(v: &Value) -> JResult<bool> {
    Ok(j_bool(v)?.unwrap_or(false))
}

/// Jackson `Double` property (wrapper).
pub fn j_f64(v: &Value) -> JResult<Option<f64>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => Ok(n.as_f64()),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return Ok(None);
            }
            match t.parse::<f64>() {
                Ok(f) => Ok(Some(f)),
                Err(_) => jerr("cannot parse double"),
            }
        }
        _ => jerr("cannot deserialize a double"),
    }
