        Value::Number(n) => java_number(n),
        Value::Array(a) => {
            let parts: Vec<String> = a.iter().map(java_nested).collect();
            format!("[{}]", parts.join(", "))
        }
        Value::Object(o) => {
            let parts: Vec<String> = o
                .iter()
                .map(|(k, v)| format!("{}={}", k, java_nested(v)))
                .collect();
            format!("{{{}}}", parts.join(", "))
        }
    }
}

/// `PropertyValueConverter.convertToEntityAttribute`: typed read-back of a stored string.
pub fn prop_from_db(s: &str) -> Value {
    if s.eq_ignore_ascii_case("true") {
        return Value::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return Value::Bool(false);
    }
    if commons_is_parsable(s) {
        let digits_only = |t: &str| !t.is_empty() && t.chars().all(|c| c.is_ascii_digit());
        if digits_only(s) || (s.starts_with('-') && digits_only(&s[1..])) {
            if let Ok(i) = s.parse::<i64>() {
                return Value::from(i);
            }
            return serde_json::Number::from_f64(s.parse::<f64>().unwrap_or(0.0))
                .map(Value::Number)
                .unwrap_or(Value::Null);
        }
        return match s.parse::<f64>() {
            Ok(f) => serde_json::Number::from_f64(f)
                .map(Value::Number)
                .unwrap_or(Value::Null),
            Err(_) => Value::String(s.to_string()),
        };
    }
    Value::String(s.to_string())
}

/// `org.apache.commons.lang3.math.NumberUtils.isParsable` (3.x semantics).
fn commons_is_parsable(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    if s.ends_with('.') {
        return false;
    }
    let body = if let Some(rest) = s.strip_prefix('-') {
        if rest.is_empty() {
            return false;
        }
        rest
    } else {
        s
    };
    let mut dots = 0;
    for c in body.chars() {
        if c == '.' {
            dots += 1;
            if dots > 1 {
                return false;
            }
        } else if !c.is_ascii_digit() {
            return false;
        }
    }
    true
}

/// Parses a JSON document and returns its first value (Jackson ignores trailing tokens).
pub fn parse_first(body: &[u8]) -> Result<Value, serde_json::Error> {
    let mut de = serde_json::Deserializer::from_slice(body);
    Value::deserialize_first(&mut de)
}

trait DeserializeFirst {
    fn deserialize_first(de: &mut serde_json::Deserializer<serde_json::de::SliceRead<'_>>)
        -> Result<Value, serde_json::Error>;
}

impl DeserializeFirst for Value {
    fn deserialize_first(
        de: &mut serde_json::Deserializer<serde_json::de::SliceRead<'_>>,
    ) -> Result<Value, serde_json::Error> {
        use serde::Deserialize;
        Value::deserialize(de)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn java_double_format() {
        assert_eq!(java_double(1.0), "1.0");
        assert_eq!(java_double(0.5), "0.5");
        assert_eq!(java_double(1e7), "1.0E7");
        assert_eq!(java_double(1.5e-5), "1.5E-5");
        assert_eq!(java_double(20026376.39), "2.002637639E7");
        assert_eq!(java_double(-3.0), "-3.0");
    }

    #[test]
