        assert_eq!(prop_from_db("12"), Value::from(12));
        assert_eq!(prop_from_db("-3"), Value::from(-3));
        assert_eq!(prop_from_db("true"), Value::Bool(true));
        assert_eq!(prop_from_db("x y"), Value::String("x y".into()));
        assert_eq!(prop_from_db("1.5"), serde_json::json!(1.5));
        assert_eq!(prop_from_db("1.0E10"), Value::String("1.0E10".into()));
        assert_eq!(prop_from_db("1."), Value::String("1.".into()));
    }

    #[test]
    fn conversions() {
        assert_eq!(conv_int("abc"), 0);
        assert_eq!(conv_int("4.0"), 0);
        assert_eq!(conv_int(" 7 "), 7);
        assert!(conv_bool("yes"));
