//! The generic part of the REST resources: the `Res` trait every entity
//! implements, and the `output:only` / `/filter` semantics of
//! `AbstractCrudService` and `EntityUtil`.

use async_trait::async_trait;
use serde::Serialize;
use serde_json::{Map, Value};

use crate::acl::Ent;
use crate::db::{Ctx, DbResult, Touched};
use crate::jv::{conv_bool, conv_f64, conv_int, j_object, JErr, JResult};
use sqlx::PgConnection;

/// Field types, as the Java field types decide the conversion of filter values.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FT {
    Int,
    Str,
    Bool,
    F64,
}

/// A converted filter value.
#[derive(Clone, Debug, PartialEq)]
pub enum FVal {
    Int(i32),
    Str(String),
    Bool(bool),
    F64(f64),
}

impl FVal {
    fn convert(raw: &str, ft: FT) -> FVal {
        match ft {
            FT::Int => FVal::Int(conv_int(raw)),
            FT::Str => FVal::Str(raw.to_string()),
            FT::Bool => FVal::Bool(conv_bool(raw)),
            FT::F64 => FVal::F64(conv_f64(raw)),
        }
    }

    /// Equality of a stored JSON value with this filter value (`Restrictions.eq`).
    fn matches(&self, v: &Value) -> bool {
        match self {
            FVal::Int(i) => v.as_i64() == Some(*i as i64),
            FVal::Str(s) => v.as_str() == Some(s.as_str()),
            FVal::Bool(b) => v.as_bool() == Some(*b),
            FVal::F64(f) => v.as_f64() == Some(*f),
        }
    }
}

/// Every REST resource of the slice.
#[async_trait]
pub trait Res: Serialize + Clone + Send + Sync + 'static {
    const ENT: Ent;
    /// Filterable and restrictable fields: the primitive, wrapper and String
    /// fields of the entity class hierarchy, by their JSON name.
    const FIELDS: &'static [(&'static str, FT)];

    /// The state of `new X()` in the original.
    fn new_default() -> Self;
    fn id(&self) -> Option<i32>;
    /// Applies one property of a JSON object, as Jackson's bean deserialiser does.
    fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()>;
    /// Loads the entities (all of them, or the given ids), fully populated.
    async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Self>>;
    /// Inserts (no id yet) or updates; `t` tells which keys have to be persisted.
    async fn write(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()>;
    async fn delete(&self, cx: &mut Ctx<'_>) -> DbResult<()>;
}

/// Parses the body of a nested object (Jackson creates a new instance with the
/// constructor defaults and sets the given properties).
pub fn nested<T: Res>(v: &Value) -> JResult<T> {
    let o = j_object(v)?;
    let mut t = T::new_default();
    for (k, val) in o {
        t.apply_key(k, val)?;
    }
    Ok(t)
}

/// Properties Jackson ignores silently on every persistent object.
pub fn ignored_key(k: &str) -> bool {
    matches!(k, "created" | "modified" | "userPermissions" | "groupPermissions")
}

pub fn unknown(k: &str) -> JErr {
    JErr(format!("Unrecognized field \"{}\"", k))
}

/// Parses the query string into (key, value) pairs, keeping order and repeats.
pub fn parse_query(raw: Option<&str>) -> Vec<(String, String)> {
    match raw {
        Some(q) => form_urlencoded::parse(q.as_bytes())
            .map(|(k, v)| (k.into_owned(), v.into_owned()))
            .collect(),
        None => Vec::new(),
    }
}

/// `EntityUtil.determineRestrictFields`: the restrictable fields named by
/// `output:only`, or `None` when no valid field is named.
pub fn restrict_fields<T: Res>(q: &[(String, String)]) -> Option<Vec<&'static str>> {
    let mut requested: Vec<String> = Vec::new();
    for (k, v) in q {
        if k.eq_ignore_ascii_case("output:only") {
            requested.extend(split_list(v));
        }
    }
    let mut out: Vec<&'static str> = Vec::new();
    for (field, _) in T::FIELDS {
        if requested.iter().any(|r| r.eq_ignore_ascii_case(field)) {
            out.push(field);
        }
    }
    if out.is_empty() {
        None
    } else {
        Some(out)
    }
}

/// `split("\\s*,\\s*")` as Java does it (no trimming of the outer ends).
fn split_list(s: &str) -> Vec<String> {
    let parts: Vec<&str> = s.split(',').collect();
    let n = parts.len();
    parts
        .into_iter()
        .enumerate()
        .map(|(i, p)| {
            let mut t = p;
            if i > 0 {
                t = t.trim_start();
            }
            if i + 1 < n {
                t = t.trim_end();
            }
            t.to_string()
        })
        .collect()
}

/// `AbstractCrudService.findBySimpleFilter`: the valid filter fields with their
/// converted values. Empty when no valid field is named (the result is then empty).
pub fn filter_criteria<T: Res>(q: &[(String, String)]) -> Vec<(&'static str, Vec<FVal>)> {
    let mut out: Vec<(&'static str, Vec<FVal>)> = Vec::new();
    for (k, v) in q {
        if k.eq_ignore_ascii_case("output:only") {
            continue;
        }
        let Some((field, ft)) = T::FIELDS.iter().find(|(f, _)| f.eq_ignore_ascii_case(k)) else {
            continue;
        };
        let val = FVal::convert(v, *ft);
        match out.iter_mut().find(|(f, _)| f == field) {
            Some((_, vals)) => vals.push(val),
            None => out.push((field, vec![val])),
        }
    }
    out
}

/// Does the entity (as JSON) satisfy every criterion? Values of one field are OR-ed.
pub fn matches_criteria(json: &Value, criteria: &[(&'static str, Vec<FVal>)]) -> bool {
    criteria.iter().all(|(field, vals)| {
        let v = json.get(*field).unwrap_or(&Value::Null);
        vals.iter().any(|fv| fv.matches(v))
    })
}

/// The restricted object of `output:only`: the constructor defaults with the
/// projected fields copied from the stored entity.
pub fn project(full: &Value, default: &Value, fields: &[&str]) -> Value {
    let mut out: Map<String, Value> = default.as_object().cloned().unwrap_or_default();
    for f in fields {
        if let Some(v) = full.get(*f) {
            out.insert((*f).to_string(), v.clone());
        }
    }
    Value::Object(out)
}

