//! `User` (with `Person`), `UserGroup` and `Role`.

use async_trait::async_trait;
use serde::Serialize;
use serde_json::Value;
use sqlx::{PgConnection, Row};

use crate::acl::Ent;
use crate::db::{alloc_id, dberr, expect_one, Ctx, DbResult, Touched};
use crate::jv::{j_bool_prim, j_date, j_int, j_list, j_locale, j_string, j_object, JResult};
use crate::res::{ignored_key, nested, unknown, FT, Res};

// ---------------------------------------------------------------- Role

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct Role {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
}

impl Role {
    fn ids_of(list: &[Role]) -> Vec<i32> {
        let mut v: Vec<i32> = list.iter().filter_map(|r| r.id).collect();
        v.sort_unstable();
        v.dedup();
        v
    }
}

#[async_trait]
impl Res for Role {
    const ENT: Ent = Ent::Role;
    const FIELDS: &'static [(&'static str, FT)] = &[
        ("id", FT::Int),
        ("name", FT::Str),
        ("description", FT::Str),
    ];

    fn new_default() -> Self {
        Role::default()
    }

    fn id(&self) -> Option<i32> {
        self.id
    }

    fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()> {
        match key {
            "id" => self.id = j_int(v)?,
            "name" => self.name = j_string(v)?,
            "description" => self.description = j_string(v)?,
            k if ignored_key(k) => {}
            k => return Err(unknown(k)),
        }
        Ok(())
    }

    async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Self>> {
        let ids: Option<Vec<i32>> = ids.map(|s| s.to_vec());
        let rows = sqlx::query(
            "SELECT id, name, description FROM roles \
             WHERE ($1::int4[] IS NULL OR id = ANY($1)) ORDER BY id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut out = Vec::new();
        for r in rows {
            out.push(Role {
                id: Some(r.try_get("id")?),
                name: r.try_get("name")?,
                description: r.try_get("description")?,
            });
        }
        Ok(out)
    }

    async fn write(&mut self, cx: &mut Ctx<'_>, _t: &Touched) -> DbResult<()> {
        match self.id {
            None => {
                let id = alloc_id(cx.pool).await?;
                self.id = Some(id);
                sqlx::query(
                    "INSERT INTO roles (id, created, modified, description, name) \
                     VALUES ($1, now(), now(), $2, $3)",
                )
                .bind(id)
                .bind(&self.description)
                .bind(&self.name)
                .execute(&mut *cx.c)
                .await?;
            }
            Some(id) => {
                let rows = sqlx::query(
                    "UPDATE roles SET modified = CASE WHEN $4 THEN now() ELSE modified END, \
                     description = $2, name = $3 WHERE id = $1",
                )
                .bind(id)
                .bind(&self.description)
                .bind(&self.name)
                .bind(cx.touch_modified)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "roles")?;
            }
        }
        Ok(())
    }

    async fn delete(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let Some(id) = self.id else { return dberr("no id") };
        delete_entity_perms(cx.c, id).await?;
        sqlx::query("DELETE FROM roles WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        Ok(())
    }
}

/// The owner-side permission collections of an entity are removed with it.
pub async fn delete_entity_perms(c: &mut PgConnection, id: i32) -> DbResult<()> {
    sqlx::query("DELETE FROM userpermissions WHERE entity_id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    sqlx::query("DELETE FROM grouppermissions WHERE entity_id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    Ok(())
}

// ---------------------------------------------------------------- User

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct User {
    pub id: Option<i32>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    pub birthday: Option<String>,
    pub language: Option<String>,
    pub account_name: Option<String>,
    #[serde(skip)]
    pub password: Option<String>,
    pub active: bool,
    pub roles: Option<Vec<Role>>,
    /// Serialised as the ids of the groups (`@JsonIdentityReference(alwaysAsId)`).
    pub user_groups: Option<Vec<Option<i32>>>,
}

impl Default for User {
    fn default() -> Self {
        User {
            id: None,
            first_name: None,
            last_name: None,
            email: None,
            birthday: None,
            language: None,
            account_name: None,
            password: None,
            active: false,
            roles: Some(Vec::new()),
            user_groups: Some(Vec::new()),
        }
    }
}

#[async_trait]
impl Res for User {
    const ENT: Ent = Ent::User;
    const FIELDS: &'static [(&'static str, FT)] = &[
        ("id", FT::Int),
        ("firstName", FT::Str),
        ("lastName", FT::Str),
        ("email", FT::Str),
        ("accountName", FT::Str),
        ("password", FT::Str),
        ("active", FT::Bool),
    ];

    fn new_default() -> Self {
        User::default()
    }

    fn id(&self) -> Option<i32> {
        self.id
    }

    fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()> {
        match key {
            "id" => self.id = j_int(v)?,
            "firstName" => self.first_name = j_string(v)?,
            "lastName" => self.last_name = j_string(v)?,
            "email" => self.email = j_string(v)?,
            "birthday" => self.birthday = j_date(v)?,
            "language" => self.language = j_locale(v)?,
            "accountName" => self.account_name = j_string(v)?,
            "password" => self.password = j_string(v)?,
            "active" => self.active = j_bool_prim(v)?,
            "roles" => {
                self.roles = j_list(v, |e| {
                    if e.is_null() {
                        Ok(None)
                    } else {
                        Ok(Some(nested::<Role>(e)?))
                    }
                })?
                .map(|l| l.into_iter().map(|e| e.unwrap_or_default()).collect())
            }
            "userGroups" => {
                self.user_groups = group_refs(v)?;
            }
            k if ignored_key(k) => {}
            k => return Err(unknown(k)),
        }
        Ok(())
    }

    async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Self>> {
        let ids: Option<Vec<i32>> = ids.map(|s| s.to_vec());
        let rows = sqlx::query(
            "SELECT p.id AS id, to_char(p.birthday, 'YYYY-MM-DD') AS birthday, p.email AS email, \
             p.firstname AS firstname, p.language AS language, p.lastname AS lastname, \
             u.accountname AS accountname, u.active AS active, u.password AS password \
             FROM users u JOIN persons p ON p.id = u.id \
             WHERE ($1::int4[] IS NULL OR u.id = ANY($1)) ORDER BY u.id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut out: Vec<User> = Vec::with_capacity(rows.len());
        for r in rows {
            out.push(User {
                id: Some(r.try_get("id")?),
                first_name: r.try_get("firstname")?,
                last_name: r.try_get("lastname")?,
                email: r.try_get("email")?,
                birthday: r.try_get("birthday")?,
                language: r.try_get("language")?,
                account_name: r.try_get("accountname")?,
                password: r.try_get("password")?,
                active: r.try_get("active")?,
                roles: Some(Vec::new()),
                user_groups: Some(Vec::new()),
            });
        }
        let role_rows = sqlx::query(
            "SELECT ur.user_id AS uid, r.id AS id, r.name AS name, r.description AS description \
             FROM users_roles ur JOIN roles r ON r.id = ur.role_id \
             WHERE ($1::int4[] IS NULL OR ur.user_id = ANY($1)) ORDER BY r.id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for r in role_rows {
            let uid: i32 = r.try_get("uid")?;
            if let Some(u) = out.iter_mut().find(|u| u.id == Some(uid)) {
                u.roles.get_or_insert_with(Vec::new).push(Role {
                    id: Some(r.try_get("id")?),
                    name: r.try_get("name")?,
                    description: r.try_get("description")?,
                });
            }
        }
        let group_rows = sqlx::query(
            "SELECT user_id, usergroup_id FROM user_usergroup \
             WHERE ($1::int4[] IS NULL OR user_id = ANY($1)) ORDER BY usergroup_id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for r in group_rows {
            let uid: i32 = r.try_get("user_id")?;
            let gid: i32 = r.try_get("usergroup_id")?;
            if let Some(u) = out.iter_mut().find(|u| u.id == Some(uid)) {
                u.user_groups.get_or_insert_with(Vec::new).push(Some(gid));
            }
        }
        Ok(out)
    }

    async fn write(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()> {
        let is_new = self.id.is_none();
        let id = match self.id {
            Some(id) => id,
            None => {
                let id = alloc_id(cx.pool).await?;
                self.id = Some(id);
                id
            }
        };
        if is_new {
            sqlx::query(
                "INSERT INTO persons (id, created, modified, birthday, email, firstname, language, lastname) \
                 VALUES ($1, now(), now(), $2::date, $3, $4, $5, $6)",
            )
            .bind(id)
            .bind(&self.birthday)
            .bind(&self.email)
            .bind(&self.first_name)
            .bind(&self.language)
            .bind(&self.last_name)
            .execute(&mut *cx.c)
            .await?;
            sqlx::query("INSERT INTO users (id, accountname, active, password) VALUES ($1, $2, $3, $4)")
                .bind(id)
                .bind(&self.account_name)
                .bind(self.active)
                .bind(&self.password)
                .execute(&mut *cx.c)
                .await?;
        } else {
            let rows = sqlx::query(
                "UPDATE persons SET modified = CASE WHEN $9 THEN now() ELSE modified END, \
                 birthday = $2::date, email = $3, firstname = $4, language = $5, lastname = $6 WHERE id = $1",
            )
            .bind(id)
            .bind(&self.birthday)
            .bind(&self.email)
            .bind(&self.first_name)
            .bind(&self.language)
            .bind(&self.last_name)
            .bind(cx.touch_modified)
            .bind(cx.touch_modified)
            .execute(&mut *cx.c)
            .await?
            .rows_affected();
            expect_one(rows, "persons")?;
            let rows = sqlx::query("UPDATE users SET accountname = $2, active = $3, password = $4 WHERE id = $1")
                .bind(id)
                .bind(&self.account_name)
                .bind(self.active)
                .bind(&self.password)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
            expect_one(rows, "users")?;
        }
        if t.has("roles") {
            sqlx::query("DELETE FROM users_roles WHERE user_id = $1")
                .bind(id)
                .execute(&mut *cx.c)
                .await?;
            for rid in Role::ids_of(self.roles.as_deref().unwrap_or(&[])) {
                sqlx::query("INSERT INTO users_roles (user_id, role_id) VALUES ($1, $2)")
                    .bind(id)
                    .bind(rid)
                    .execute(&mut *cx.c)
                    .await?;
            }
            if self.roles.as_deref().map(|r| r.iter().any(|x| x.id.is_none())).unwrap_or(false) {
                return dberr("transient role");
            }
        }
        if t.has("userGroups") {
            sqlx::query("DELETE FROM user_usergroup WHERE user_id = $1")
                .bind(id)
                .execute(&mut *cx.c)
                .await?;
            for gid in group_ids(self.user_groups.as_deref().unwrap_or(&[]))? {
                sqlx::query("INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)")
                    .bind(gid)
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
            }
        }
        Ok(())
    }

    async fn delete(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let Some(id) = self.id else { return dberr("no id") };
        sqlx::query("DELETE FROM users_roles WHERE user_id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        sqlx::query("DELETE FROM user_usergroup WHERE user_id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        delete_entity_perms(cx.c, id).await?;
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        sqlx::query("DELETE FROM persons WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        Ok(())
    }
}

/// The `userGroups` property: ids, or objects carrying an id (`UserGroupIdResolver`).
fn group_refs(v: &Value) -> JResult<Option<Vec<Option<i32>>>> {
    Ok(j_list(v, |e| match e {
        Value::Null => Ok(None),
        Value::Object(_) => Ok(Some(nested::<UserGroup>(e)?.id)),
        other => j_int(other),
    })?
    .map(|l| l.into_iter().map(|x| x.flatten()).collect()))
}

/// Group ids of a user's group list; a missing id fails the write (transient entity).
fn group_ids(list: &[Option<i32>]) -> DbResult<Vec<i32>> {
    let mut out = Vec::new();
    for g in list {
        match g {
            Some(id) => {
                if !out.contains(id) {
                    out.push(*id);
                }
            }
            None => return dberr("transient user group"),
        }
    }
    Ok(out)
}

// ---------------------------------------------------------------- UserGroup

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct UserGroup {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub owner: Option<Box<User>>,
    pub members: Option<Vec<User>>,
    pub roles: Option<Vec<Role>>,
}

impl Default for UserGroup {
    fn default() -> Self {
        UserGroup {
            id: None,
            name: None,
            owner: None,
            members: Some(Vec::new()),
            roles: Some(Vec::new()),
        }
    }
}

#[async_trait]
impl Res for UserGroup {
    const ENT: Ent = Ent::Group;
    const FIELDS: &'static [(&'static str, FT)] = &[("id", FT::Int), ("name", FT::Str)];

    fn new_default() -> Self {
        UserGroup::default()
    }

    fn id(&self) -> Option<i32> {
        self.id
    }

    fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()> {
        match key {
            "id" => self.id = j_int(v)?,
            "name" => self.name = j_string(v)?,
            "owner" => {
                self.owner = if v.is_null() {
                    None
                } else {
                    Some(Box::new(nested::<User>(v)?))
                }
            }
            "members" => {
                self.members = j_list(v, |e| {
                    if e.is_null() {
                        Ok(None)
                    } else {
                        Ok(Some(nested::<User>(e)?))
                    }
                })?
                .map(|l| l.into_iter().map(|e| e.unwrap_or_default()).collect())
            }
            "roles" => {
                self.roles = j_list(v, |e| {
                    if e.is_null() {
                        Ok(None)
                    } else {
                        Ok(Some(nested::<Role>(e)?))
                    }
                })?
                .map(|l| l.into_iter().map(|e| e.unwrap_or_default()).collect())
            }
            k if ignored_key(k) => {}
            k => return Err(unknown(k)),
        }
        Ok(())
    }

    async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Self>> {
        let ids: Option<Vec<i32>> = ids.map(|s| s.to_vec());
        let rows = sqlx::query(
            "SELECT id, name, owner_id FROM usergroups \
             WHERE ($1::int4[] IS NULL OR id = ANY($1)) ORDER BY id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut groups: Vec<(i32, UserGroup, Option<i32>)> = Vec::new();
        for r in rows {
            let id: i32 = r.try_get("id")?;
            let owner_id: Option<i32> = r.try_get("owner_id")?;
            groups.push((
                id,
                UserGroup {
                    id: Some(id),
                    name: r.try_get("name")?,
                    owner: None,
                    members: Some(Vec::new()),
                    roles: Some(Vec::new()),
                },
                owner_id,
            ));
        }
        // owner (a full user)
        let owner_ids: Vec<i32> = groups.iter().filter_map(|g| g.2).collect();
        let owners = User::load(c, Some(&owner_ids)).await?;
        // members
        let member_rows = sqlx::query(
            "SELECT usergroup_id, user_id FROM user_usergroup \
             WHERE ($1::int4[] IS NULL OR usergroup_id = ANY($1)) ORDER BY user_id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut member_map: Vec<(i32, i32)> = Vec::new();
        for r in member_rows {
            member_map.push((r.try_get("usergroup_id")?, r.try_get("user_id")?));
        }
        let member_user_ids: Vec<i32> = member_map.iter().map(|m| m.1).collect();
        let members = User::load(c, Some(&member_user_ids)).await?;
        // roles
        let role_rows = sqlx::query(
            "SELECT gr.usergroup_id AS gid, r.id AS id, r.name AS name, r.description AS description \
             FROM usergroups_roles gr JOIN roles r ON r.id = gr.role_id \
             WHERE ($1::int4[] IS NULL OR gr.usergroup_id = ANY($1)) ORDER BY r.id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut role_map: Vec<(i32, Role)> = Vec::new();
        for r in role_rows {
            role_map.push((
                r.try_get("gid")?,
                Role {
                    id: Some(r.try_get("id")?),
                    name: r.try_get("name")?,
                    description: r.try_get("description")?,
                },
            ));
        }

        let mut out = Vec::with_capacity(groups.len());
        for (id, mut g, owner_id) in groups {
            g.owner = owner_id.and_then(|oid| owners.iter().find(|u| u.id == Some(oid)).cloned().map(Box::new));
            let mut mem = Vec::new();
            for (gid, uid) in &member_map {
                if *gid == id {
                    if let Some(u) = members.iter().find(|u| u.id == Some(*uid)) {
                        mem.push(u.clone());
                    }
                }
            }
            g.members = Some(mem);
            g.roles = Some(role_map.iter().filter(|(gid, _)| *gid == id).map(|(_, r)| r.clone()).collect());
            out.push(g);
        }
        Ok(out)
    }

    async fn write(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()> {
        let is_new = self.id.is_none();
        let id = match self.id {
            Some(id) => id,
            None => {
                let id = alloc_id(cx.pool).await?;
                self.id = Some(id);
                id
            }
        };
        let owner_id = match &self.owner {
            None => None,
            Some(o) => match o.id {
                Some(oid) => Some(oid),
                None => return dberr("transient owner"),
            },
        };
        if is_new {
            sqlx::query(
                "INSERT INTO usergroups (id, created, modified, name, owner_id) VALUES ($1, now(), now(), $2, $3)",
            )
            .bind(id)
            .bind(&self.name)
            .bind(owner_id)
            .execute(&mut *cx.c)
            .await?;
        } else {
            let rows = sqlx::query(
                "UPDATE usergroups SET modified = CASE WHEN $4 THEN now() ELSE modified END, \
                 name = $2, owner_id = $3 WHERE id = $1",
            )
            .bind(id)
            .bind(&self.name)
            .bind(owner_id)
            .bind(cx.touch_modified)
            .execute(&mut *cx.c)
            .await?
            .rows_affected();
            expect_one(rows, "usergroups")?;
        }
        if t.has("members") {
            sqlx::query("DELETE FROM user_usergroup WHERE usergroup_id = $1")
                .bind(id)
                .execute(&mut *cx.c)
                .await?;
            let mut seen: Vec<i32> = Vec::new();
            for m in self.members.as_deref().unwrap_or(&[]) {
                let Some(uid) = m.id else { return dberr("transient member") };
                if seen.contains(&uid) {
                    continue;
                }
                seen.push(uid);
                sqlx::query("INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)")
                    .bind(id)
                    .bind(uid)
                    .execute(&mut *cx.c)
                    .await?;
            }
        }
        if t.has("roles") {
            sqlx::query("DELETE FROM usergroups_roles WHERE usergroup_id = $1")
                .bind(id)
                .execute(&mut *cx.c)
                .await?;
            let mut seen: Vec<i32> = Vec::new();
            for r in self.roles.as_deref().unwrap_or(&[]) {
                let Some(rid) = r.id else { return dberr("transient role") };
                if seen.contains(&rid) {
                    continue;
                }
                seen.push(rid);
                sqlx::query("INSERT INTO usergroups_roles (usergroup_id, role_id) VALUES ($1, $2)")
                    .bind(id)
                    .bind(rid)
                    .execute(&mut *cx.c)
                    .await?;
            }
        }
        Ok(())
    }

    async fn delete(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let Some(id) = self.id else { return dberr("no id") };
        sqlx::query("DELETE FROM user_usergroup WHERE usergroup_id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        sqlx::query("DELETE FROM usergroups_roles WHERE usergroup_id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        delete_entity_perms(cx.c, id).await?;
        sqlx::query("DELETE FROM usergroups WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        Ok(())
    }
}

/// Used by the user/group sub-resources: a user's groups, as full objects.
pub fn groups_of(user: &User) -> Vec<i32> {
    user.user_groups
        .as_deref()
        .unwrap_or(&[])
        .iter()
        .filter_map(|g| *g)
        .collect()
}

/// Keeps the compiler honest about `Row` usage in this module.
#[allow(dead_code)]
fn _unused(_: &dyn Fn(&Value) -> JResult<()>) {
    let _ = j_object;
}

