    pub attribution: Option<String>,
    pub hoverable: Option<bool>,
    pub clickable: Option<bool>,
    pub hover_template: Option<String>,
    pub properties: Option<Map<String, Value>>,
    pub name: Option<String>,
    pub max_resolution: Option<f64>,
    pub min_resolution: Option<f64>,
    pub opacity: Option<f64>,
    pub visible: Option<bool>,
}

impl Default for Appearance {
    fn default() -> Self {
        Appearance {
            id: None,
            attribution: None,
            hoverable: None,
            clickable: None,
            hover_template: None,
            properties: Some(Map::new()),
            name: None,
            max_resolution: None,
            min_resolution: None,
            opacity: None,
            visible: None,
        }
    }
}

impl Appearance {
    /// Writes the row and, when the properties are to be persisted, the
    /// property rows (null values are not stored).
    pub async fn save(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()> {
