            )
            .bind(id)
            .bind(&self.attribution)
            .bind(self.clickable)
            .bind(&self.hover_template)
            .bind(self.hoverable)
            .bind(self.max_resolution)
            .bind(self.min_resolution)
            .bind(&self.name)
            .bind(self.opacity)
            .bind(self.visible)
            .execute(&mut *cx.c)
            .await?;
        } else {
            let rows = sqlx::query(
                "UPDATE layerappearances SET modified = CASE WHEN $11 THEN now() ELSE modified END, \
                 attribution = $2, clickable = $3, hovertemplate = $4, hoverable = $5, maxresolution = $6, \
                 minresolution = $7, name = $8, opacity = $9, visible = $10 WHERE id = $1",
            )
            .bind(id)
            .bind(&self.attribution)
            .bind(self.clickable)
            .bind(&self.hover_template)
            .bind(self.hoverable)
            .bind(self.max_resolution)
            .bind(self.min_resolution)
            .bind(&self.name)
            .bind(self.opacity)
            .bind(self.visible)
            .bind(cx.touch_modified)
            .execute(&mut *cx.c)
            .await?
            .rows_affected();
            expect_one(rows, "layerappearances")?;
        }
        if t.has("properties") {
            sqlx::query("DELETE FROM layerappearances_properties WHERE appearance_id = $1")
                .bind(id)
                .execute(&mut *cx.c)
