                for (k, v) in props {
                    if let Some(s) = java_to_string(v) {
                        sqlx::query(
                            "INSERT INTO layerappearances_properties (appearance_id, property, value) \
                             VALUES ($1, $2, $3)",
                        )
                        .bind(id)
                        .bind(k)
