}

#[async_trait]
impl Res for Appearance {
    const ENT: Ent = Ent::Appearance;
    const FIELDS: &'static [(&'static str, FT)] = &[
        ("id", FT::Int),
        ("attribution", FT::Str),
        ("hoverable", FT::Bool),
        ("clickable", FT::Bool),
        ("hoverTemplate", FT::Str),
        ("name", FT::Str),
        ("maxResolution", FT::F64),
        ("minResolution", FT::F64),
        ("opacity", FT::F64),
        ("visible", FT::Bool),
    ];

    fn new_default() -> Self {
        Appearance::default()
    }

    fn id(&self) -> Option<i32> {
        self.id
    }

    fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()> {
        match key {
            "id" => self.id = crate::jv::j_int(v)?,
            "attribution" => self.attribution = j_string(v)?,
            "hoverable" => self.hoverable = j_bool(v)?,
            "clickable" => self.clickable = j_bool(v)?,
            "hoverTemplate" => self.hover_template = j_string(v)?,
            "properties" => {
                self.properties = match v {
                    Value::Null => None,
                    Value::Object(o) => Some(o.clone()),
                    _ => return jerr("cannot deserialize a Map"),
                }
            }
