            "maxResolution" => self.max_resolution = j_f64(v)?,
            "minResolution" => self.min_resolution = j_f64(v)?,
            "opacity" => self.opacity = j_f64(v)?,
            "visible" => self.visible = j_bool(v)?,
            k if ignored_key(k) => {}
            k => return Err(unknown(k)),
        }
        Ok(())
    }

    async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Self>> {
        Appearance::load_ids(c, ids).await
    }

    async fn write(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()> {
        self.save(cx, t).await
    }

    async fn delete(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let Some(id) = self.id else { return dberr("no id") };
        sqlx::query("DELETE FROM layerappearances_properties WHERE appearance_id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        delete_entity_perms(cx.c, id).await?;
        sqlx::query("DELETE FROM layerappearances WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        Ok(())
    }
}

impl Appearance {
    pub async fn load_ids(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Appearance>> {
        let ids: Option<Vec<i32>> = ids.map(|s| s.to_vec());
        let rows = sqlx::query(
            "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution, minresolution, \
             name, opacity, visible FROM layerappearances \
             WHERE ($1::int4[] IS NULL OR id = ANY($1)) ORDER BY id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut out = Vec::with_capacity(rows.len());
        for r in rows {
            out.push(Appearance {
                id: Some(r.try_get("id")?),
                attribution: r.try_get("attribution")?,
                hoverable: r.try_get("hoverable")?,
                clickable: r.try_get("clickable")?,
                hover_template: r.try_get("hovertemplate")?,
                properties: Some(Map::new()),
                name: r.try_get("name")?,
                max_resolution: r.try_get("maxresolution")?,
                min_resolution: r.try_get("minresolution")?,
                opacity: r.try_get("opacity")?,
                visible: r.try_get("visible")?,
            });
        }
        let prop_rows = sqlx::query(
            "SELECT appearance_id, property, value FROM layerappearances_properties \
             WHERE ($1::int4[] IS NULL OR appearance_id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for r in prop_rows {
            let aid: i32 = r.try_get("appearance_id")?;
            let key: String = r.try_get("property")?;
            let value: Option<String> = r.try_get("value")?;
            if let Some(app) = out.iter_mut().find(|a| a.id == Some(aid)) {
                let v = value.as_deref().map(prop_from_db).unwrap_or(Value::Null);
                app.properties.get_or_insert_with(Map::new).insert(key, v);
            }
        }
        Ok(out)
    }
}

// ---------------------------------------------------------------- Layer

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct Layer {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
    pub source: Option<Box<Lds>>,
    pub appearance: Option<Box<Appearance>>,
}

impl Default for Layer {
    fn default() -> Self {
        Layer {
            id: None,
            name: None,
            description: None,
            source: None,
            appearance: None,
        }
    }
}

#[async_trait]
impl Res for Layer {
    const ENT: Ent = Ent::Layer;
    const FIELDS: &'static [(&'static str, FT)] = &[
        ("id", FT::Int),
        ("name", FT::Str),
        ("description", FT::Str),
    ];

    fn new_default() -> Self {
        Layer::default()
    }

    fn id(&self) -> Option<i32> {
        self.id
    }

    fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()> {
        match key {
            "id" => self.id = crate::jv::j_int(v)?,
            "name" => self.name = j_string(v)?,
            "description" => self.description = j_string(v)?,
            "source" => {
                // LayerDataSource is abstract: Jackson cannot build it from JSON.
                if !v.is_null() {
                    return jerr("Cannot construct instance of LayerDataSource (abstract)");
                }
                self.source = None;
            }
            "appearance" => {
                self.appearance = if v.is_null() {
                    None
                } else {
                    Some(Box::new(nested::<Appearance>(v)?))
                }
            }
            k if ignored_key(k) => {}
            k => return Err(unknown(k)),
        }
        Ok(())
    }

    async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Self>> {
        let ids: Option<Vec<i32>> = ids.map(|s| s.to_vec());
        let rows = sqlx::query(
            "SELECT id, name, description, appearance_id, source_id FROM layers \
             WHERE ($1::int4[] IS NULL OR id = ANY($1)) ORDER BY id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut layers: Vec<(Layer, Option<i32>, Option<i32>)> = Vec::with_capacity(rows.len());
        for r in rows {
            let app_id: Option<i32> = r.try_get("appearance_id")?;
            let src_id: Option<i32> = r.try_get("source_id")?;
            layers.push((
                Layer {
                    id: Some(r.try_get("id")?),
                    name: r.try_get("name")?,
                    description: r.try_get("description")?,
                    source: None,
                    appearance: None,
                },
                app_id,
                src_id,
            ));
        }
        let app_ids: Vec<i32> = layers.iter().filter_map(|l| l.1).collect();
        let src_ids: Vec<i32> = layers.iter().filter_map(|l| l.2).collect();
        let apps = Appearance::load_ids(c, Some(&app_ids)).await?;
        let srcs = Lds::load(c, Some(&src_ids)).await?;
        Ok(layers
            .into_iter()
            .map(|(mut l, app_id, src_id)| {
                l.appearance = app_id.and_then(|a| apps.iter().find(|x| x.id == Some(a)).cloned().map(Box::new));
                l.source = src_id.and_then(|s| srcs.iter().find(|x| x.id() == Some(s)).cloned().map(Box::new));
                l
            })
            .collect())
    }

    async fn write(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()> {
        let is_new = self.id.is_none();
        let id = match self.id {
            Some(id) => id,
            None => {
                let id = alloc_id(cx.pool).await?;
                self.id = Some(id);
                id
            }
        };
        // SAVE_UPDATE cascade to the appearance (after the layer's own id).
        if is_new || t.has("appearance") {
            if let Some(app) = self.appearance.as_mut() {
                app.save(cx, &Touched::All).await?;
            }
        }
        let app_id = self.appearance.as_ref().and_then(|a| a.id);
        let src_id = match &self.source {
            None => None,
            Some(s) => match s.id() {
                Some(sid) => Some(sid),
                None => return dberr("transient source"),
            },
        };
        if is_new {
            sqlx::query(
                "INSERT INTO layers (id, created, modified, description, name, appearance_id, source_id) \
                 VALUES ($1, now(), now(), $2, $3, $4, $5)",
            )
            .bind(id)
            .bind(&self.description)
            .bind(&self.name)
            .bind(app_id)
            .bind(src_id)
            .execute(&mut *cx.c)
            .await?;
        } else {
            let rows = sqlx::query(
                "UPDATE layers SET modified = CASE WHEN $6 THEN now() ELSE modified END, description = $2, \
                 name = $3, appearance_id = $4, source_id = $5 WHERE id = $1",
            )
            .bind(id)
            .bind(&self.description)
            .bind(&self.name)
            .bind(app_id)
            .bind(src_id)
            .bind(cx.touch_modified)
            .execute(&mut *cx.c)
            .await?
            .rows_affected();
            expect_one(rows, "layers")?;
        }
        Ok(())
    }

    async fn delete(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let Some(id) = self.id else { return dberr("no id") };
        // LayerService.delete removes the layer from the maps first
        sqlx::query("DELETE FROM maps_layers WHERE layer_id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        delete_entity_perms(cx.c, id).await?;
        sqlx::query("DELETE FROM layers WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        Ok(())
    }
}

