//! `Point2D.Double` values, `Extent` and `TileGrid` / `WmtsTileGrid`, the
//! embedded and related objects of the layer data sources.

use serde::Serialize;
use serde_json::Value;
use sqlx::{PgConnection, Row};

use crate::db::{alloc_id, dberr, expect_one, Ctx, DbResult, Touched};
use crate::jv::{j_f64_prim, j_int, j_list, j_string, jerr, JResult};
use crate::model::user::delete_entity_perms;
use crate::res::{ignored_key, nested, unknown};

/// `java.awt.geom.Point2D.Double` as `{x, y}`.
#[derive(Serialize, Clone, Debug, Default, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

/// A nullable point: a JSON `null`, or a row whose columns are all null, is `None`.
pub fn point_from_json(v: &Value) -> JResult<Option<Point>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(o) => {
            let mut p = Point::default();
            for (k, val) in o {
                match k.as_str() {
                    "x" => p.x = j_f64_prim(val)?,
                    "y" => p.y = j_f64_prim(val)?,
                    _ => return Err(unknown(k)),
                }
            }
            Ok(Some(p))
        }
        _ => jerr("cannot deserialize a Point2D"),
    }
}

fn point_from_cols(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    if x.is_none() && y.is_none() {
        None
    } else {
        Some(Point {
            x: x.unwrap_or(0.0),
            y: y.unwrap_or(0.0),
        })
    }
}

// ---------------------------------------------------------------- Extent

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct Extent {
    pub id: Option<i32>,
    pub lower_left: Option<Point>,
    pub upper_right: Option<Point>,
}

impl Default for Extent {
    fn default() -> Self {
        Extent {
            id: None,
            lower_left: None,
            upper_right: None,
        }
    }
}

impl Extent {
    pub fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()> {
        match key {
            "id" => self.id = j_int(v)?,
            "lowerLeft" => self.lower_left = point_from_json(v)?,
            "upperRight" => self.upper_right = point_from_json(v)?,
            k if ignored_key(k) => {}
            k => return Err(unknown(k)),
        }
        Ok(())
    }

    /// SAVE_UPDATE cascade: insert without id, otherwise overwrite the row.
    pub async fn save(&mut self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let (llx, lly) = split(&self.lower_left);
        let (urx, ury) = split(&self.upper_right);
        match self.id {
            None => {
                let id = alloc_id(cx.pool).await?;
                self.id = Some(id);
                sqlx::query(
                    "INSERT INTO extents (id, created, modified, lowerleft_x, lowerleft_y, upperright_x, upperright_y) \
                     VALUES ($1, now(), now(), $2, $3, $4, $5)",
                )
                .bind(id)
                .bind(llx)
                .bind(lly)
                .bind(urx)
                .bind(ury)
                .execute(&mut *cx.c)
                .await?;
            }
            Some(id) => {
                let rows = sqlx::query(
                    "UPDATE extents SET modified = now(), lowerleft_x = $2, lowerleft_y = $3, \
                     upperright_x = $4, upperright_y = $5 WHERE id = $1",
                )
                .bind(id)
                .bind(llx)
                .bind(lly)
                .bind(urx)
                .bind(ury)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "extents")?;
            }
        }
        Ok(())
    }

    pub async fn load_ids(c: &mut PgConnection, ids: &[i32]) -> DbResult<Vec<Extent>> {
        let ids: Vec<i32> = ids.to_vec();
        let rows = sqlx::query(
            "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents WHERE id = ANY($1)",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut out = Vec::with_capacity(rows.len());
        for r in rows {
            out.push(Extent {
                id: Some(r.try_get("id")?),
                lower_left: point_from_cols(r.try_get("lowerleft_x")?, r.try_get("lowerleft_y")?),
                upper_right: point_from_cols(r.try_get("upperright_x")?, r.try_get("upperright_y")?),
            });
        }
        Ok(out)
    }
}

fn split(p: &Option<Point>) -> (Option<f64>, Option<f64>) {
    match p {
        None => (None, None),
        Some(p) => (Some(p.x), Some(p.y)),
    }
}

// ---------------------------------------------------------------- TileGrid

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct WmtsExtra {
    pub matrix_ids: Option<Vec<Option<String>>>,
}

/// `TileGrid`; `wmts` is `Some` for the `WmtsTileGrid` subclass.
#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct TileGrid {
    pub id: Option<i32>,
    #[serde(rename = "type")]
    pub type_: Option<String>,
    pub tile_grid_origin: Option<Point>,
    pub tile_grid_extent: Option<Box<Extent>>,
    pub tile_size: Option<i32>,
    pub tile_grid_resolutions: Option<Vec<Option<f64>>>,
    #[serde(flatten)]
    pub wmts: Option<WmtsExtra>,
}

impl TileGrid {
    /// `new TileGrid()`: tile size 256.
    pub fn new_plain() -> Self {
        TileGrid {
            id: None,
            type_: None,
            tile_grid_origin: None,
            tile_grid_extent: None,
            tile_size: Some(256),
            tile_grid_resolutions: None,
            wmts: None,
        }
    }

    /// `new WmtsTileGrid()`.
    pub fn new_wmts() -> Self {
        let mut t = TileGrid::new_plain();
        t.wmts = Some(WmtsExtra { matrix_ids: None });
        t
    }

    pub fn from_json(v: &Value, wmts: bool) -> JResult<Self> {
        let mut t = if wmts { TileGrid::new_wmts() } else { TileGrid::new_plain() };
        let o = crate::jv::j_object(v)?;
        for (k, val) in o {
            t.apply_key(k, val)?;
        }
        Ok(t)
    }

    pub fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()> {
        match key {
            "id" => self.id = j_int(v)?,
            "type" => self.type_ = j_string(v)?,
            "tileGridOrigin" => self.tile_grid_origin = point_from_json(v)?,
            "tileGridExtent" => {
                self.tile_grid_extent = if v.is_null() {
                    None
                } else {
                    Some(Box::new(nested::<Extent>(v)?))
                }
            }
            "tileSize" => self.tile_size = j_int(v)?,
            "tileGridResolutions" => {
                self.tile_grid_resolutions = j_list(v, |e| crate::jv::j_f64(e))?;
            }
            "matrixIds" if self.wmts.is_some() => {
                let list = j_list(v, |e| j_string(e))?;
                if let Some(w) = self.wmts.as_mut() {
                    w.matrix_ids = list;
                }
            }
            k if ignored_key(k) => {}
            k => return Err(unknown(k)),
        }
        Ok(())
    }

    /// Writes a tile grid as a cascade target (always a JSON-built object).
    pub async fn save(&mut self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let is_new = self.id.is_none();
        let id = match self.id {
            Some(id) => id,
            None => {
                let id = alloc_id(cx.pool).await?;
                self.id = Some(id);
                id
            }
        };
        // the extent is saved (cascade) after the tile grid's own id
        if let Some(e) = self.tile_grid_extent.as_mut() {
            e.save(cx).await?;
        }
        let ext_id = self.tile_grid_extent.as_ref().and_then(|e| e.id);
        let (ox, oy) = split(&self.tile_grid_origin);
        if is_new {
            sqlx::query(
                "INSERT INTO tilegrids (id, created, modified, tilegridorigin_x, tilegridorigin_y, tilesize, type, \
                 tilegridextent_id) VALUES ($1, now(), now(), $2, $3, $4, $5, $6)",
            )
            .bind(id)
            .bind(ox)
            .bind(oy)
            .bind(self.tile_size)
            .bind(&self.type_)
            .bind(ext_id)
            .execute(&mut *cx.c)
            .await?;
        } else {
            let rows = sqlx::query(
                "UPDATE tilegrids SET modified = now(), tilegridorigin_x = $2, tilegridorigin_y = $3, \
                 tilesize = $4, type = $5, tilegridextent_id = $6 WHERE id = $1",
            )
            .bind(id)
            .bind(ox)
            .bind(oy)
            .bind(self.tile_size)
            .bind(&self.type_)
            .bind(ext_id)
            .execute(&mut *cx.c)
            .await?
            .rows_affected();
            expect_one(rows, "tilegrids")?;
        }
        sqlx::query("DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        if let Some(list) = &self.tile_grid_resolutions {
            for (idx, r) in list.iter().enumerate() {
                if let Some(r) = r {
                    sqlx::query(
                        "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES ($1, $2, $3)",
                    )
                    .bind(id)
                    .bind(r)
                    .bind(idx as i32)
                    .execute(&mut *cx.c)
                    .await?;
                }
            }
        }
        if let Some(w) = &self.wmts {
            sqlx::query("INSERT INTO wmtstilegrids (id) VALUES ($1) ON CONFLICT (id) DO NOTHING")
                .bind(id)
                .execute(&mut *cx.c)
                .await?;
            sqlx::query("DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1")
                .bind(id)
                .execute(&mut *cx.c)
                .await?;
            for m in w.matrix_ids.as_deref().unwrap_or(&[]).iter().flatten() {
                sqlx::query("INSERT INTO wmtstilegrids_matrixids (wmtstilegrids_id, matrixids) VALUES ($1, $2)")
                    .bind(id)
                    .bind(m)
                    .execute(&mut *cx.c)
                    .await?;
            }
        }
        Ok(())
    }

    /// Cascade delete (only `WmtsLayerDataSource` cascades REMOVE to its grid).
    pub async fn delete(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let Some(id) = self.id else { return dberr("no id") };
        sqlx::query("DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        if self.wmts.is_some() {
            sqlx::query("DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1")
                .bind(id)
                .execute(&mut *cx.c)
                .await?;
            sqlx::query("DELETE FROM wmtstilegrids WHERE id = $1")
                .bind(id)
                .execute(&mut *cx.c)
                .await?;
        }
        delete_entity_perms(cx.c, id).await?;
        sqlx::query("DELETE FROM tilegrids WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        Ok(())
    }

    /// Loads tile grids by id; a grid with a `wmtstilegrids` row is a WMTS grid.
    pub async fn load_ids(c: &mut PgConnection, ids: &[i32]) -> DbResult<Vec<TileGrid>> {
        let ids: Vec<i32> = ids.to_vec();
        let rows = sqlx::query(
            "SELECT id, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id \
             FROM tilegrids WHERE id = ANY($1) ORDER BY id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut out: Vec<TileGrid> = Vec::with_capacity(rows.len());
        let mut ext_ids: Vec<i32> = Vec::new();
        for r in &rows {
            let ext: Option<i32> = r.try_get("tilegridextent_id")?;
            if let Some(e) = ext {
                ext_ids.push(e);
            }
            out.push(TileGrid {
                id: Some(r.try_get("id")?),
                type_: r.try_get("type")?,
                tile_grid_origin: point_from_cols(r.try_get("tilegridorigin_x")?, r.try_get("tilegridorigin_y")?),
                tile_grid_extent: ext.map(|_| Box::new(Extent::default())),
                tile_size: r.try_get("tilesize")?,
                tile_grid_resolutions: Some(Vec::new()),
                wmts: None,
            });
        }
        let exts = Extent::load_ids(c, &ext_ids).await?;
        for t in out.iter_mut() {
            if let Some(cur) = t.tile_grid_extent.as_ref() {
                let _ = cur;
            }
        }
        // attach the extents (ids are looked up from the rows again)
        let ext_rows = sqlx::query("SELECT id, tilegridextent_id FROM tilegrids WHERE id = ANY($1) ORDER BY id")
            .bind(&ids)
            .fetch_all(&mut *c)
            .await?;
        for r in ext_rows {
            let tid: i32 = r.try_get("id")?;
            let eid: Option<i32> = r.try_get("tilegridextent_id")?;
            if let (Some(eid), Some(t)) = (eid, out.iter_mut().find(|t| t.id == Some(tid))) {
                t.tile_grid_extent = exts.iter().find(|e| e.id == Some(eid)).cloned().map(Box::new);
            }
        }
        let res_rows = sqlx::query(
            "SELECT tilegrid_id, resolution, idx FROM tilegrid_resolution WHERE tilegrid_id = ANY($1) ORDER BY idx",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for r in res_rows {
            let tid: i32 = r.try_get("tilegrid_id")?;
            let v: Option<f64> = r.try_get("resolution")?;
            if let Some(t) = out.iter_mut().find(|t| t.id == Some(tid)) {
                t.tile_grid_resolutions.get_or_insert_with(Vec::new).push(v);
            }
        }
        let wmts_rows = sqlx::query("SELECT id FROM wmtstilegrids WHERE id = ANY($1)")
            .bind(&ids)
            .fetch_all(&mut *c)
            .await?;
        let wmts_ids: Vec<i32> = wmts_rows.iter().map(|r| r.get::<i32, _>("id")).collect();
        let mx_rows = sqlx::query(
            "SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = ANY($1)",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for t in out.iter_mut() {
            if let Some(tid) = t.id {
                if wmts_ids.contains(&tid) {
                    let mut list = Vec::new();
                    for r in &mx_rows {
                        let owner: i32 = r.get("wmtstilegrids_id");
                        if owner == tid {
                            list.push(r.get::<Option<String>, _>("matrixids"));
                        }
                    }
                    t.wmts = Some(WmtsExtra { matrix_ids: Some(list) });
                }
            }
        }
        Ok(out)
    }
}

