//! `LayerDataSource` and its subtypes (JOINED inheritance, no discriminator:
//! the subtype is the table that holds the row).

use async_trait::async_trait;
use serde::{Serialize, Serializer};
use serde_json::Value;
use sqlx::{PgConnection, Row};

use crate::acl::Ent;
use crate::db::{dberr, expect_one, Ctx, DbResult, Touched};
use crate::jv::{j_bool, j_f64, j_int, j_int_prim, j_list, j_string, j_bool_prim, JResult};
use crate::model::grid::{point_from_json, Extent, Point, TileGrid};
use crate::model::user::delete_entity_perms;
use crate::res::{ignored_key, nested, unknown, FT, Res};

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct LdsBase {
    pub id: Option<i32>,
    pub name: Option<String>,
    #[serde(rename = "type")]
    pub type_: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
}

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct ImageWms {
    #[serde(flatten)]
    pub base: LdsBase,
    pub width: i32,
    pub height: i32,
    pub version: Option<String>,
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
}

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct TileWms {
    #[serde(flatten)]
    pub image: ImageWms,
    pub tile_grid: Option<Box<TileGrid>>,
    pub request_with_tiled: Option<bool>,
}

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct Wfs {
    #[serde(flatten)]
    pub base: LdsBase,
    pub version: Option<String>,
    pub type_name: Option<String>,
    pub type_names: Option<String>,
}

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct Wmts {
    #[serde(flatten)]
    pub base: LdsBase,
    pub tile_grid: Option<Box<TileGrid>>,
    pub urls: Option<Vec<Option<String>>>,
    pub wmts_layer: Option<String>,
    pub wmts_style: Option<String>,
    pub projection: Option<String>,
    pub matrix_set: Option<String>,
    pub request_encoding: Option<String>,
    pub capabilities_url: Option<String>,
}

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct Xyz {
    #[serde(flatten)]
    pub base: LdsBase,
    pub center: Option<Point>,
    pub extent: Option<Box<Extent>>,
    pub resolutions: Option<Vec<Option<f64>>>,
    pub tile_size: Option<i32>,
}

#[derive(Clone, Debug)]
pub enum Lds {
    Base(LdsBase),
    ImageWms(ImageWms),
    TileWms(TileWms),
    Wfs(Wfs),
    Wmts(Wmts),
    Xyz(Xyz),
}

impl Serialize for Lds {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            Lds::Base(x) => x.serialize(s),
            Lds::ImageWms(x) => x.serialize(s),
            Lds::TileWms(x) => x.serialize(s),
            Lds::Wfs(x) => x.serialize(s),
            Lds::Wmts(x) => x.serialize(s),
            Lds::Xyz(x) => x.serialize(s),
        }
    }
}

impl Default for Xyz {
    fn default() -> Self {
        Xyz {
            base: LdsBase::default(),
            center: None,
            extent: None,
            resolutions: Some(Vec::new()),
            tile_size: None,
        }
    }
}

impl Default for TileWms {
    fn default() -> Self {
        TileWms {
            image: ImageWms::default(),
            tile_grid: None,
            request_with_tiled: Some(true),
        }
    }
}

impl Default for Lds {
    fn default() -> Self {
        Lds::Base(LdsBase::default())
    }
}

impl Lds {
    pub fn id(&self) -> Option<i32> {
        self.base_ref().id
    }

    fn base_ref(&self) -> &LdsBase {
        match self {
            Lds::Base(b) => b,
            Lds::ImageWms(x) => &x.base,
            Lds::TileWms(x) => &x.image.base,
            Lds::Wfs(x) => &x.base,
            Lds::Wmts(x) => &x.base,
            Lds::Xyz(x) => &x.base,
        }
    }

    fn base_mut(&mut self) -> &mut LdsBase {
        match self {
            Lds::Base(b) => b,
            Lds::ImageWms(x) => &mut x.base,
            Lds::TileWms(x) => &mut x.image.base,
            Lds::Wfs(x) => &mut x.base,
            Lds::Wmts(x) => &mut x.base,
            Lds::Xyz(x) => &mut x.base,
        }
    }

    fn apply_common(b: &mut LdsBase, key: &str, v: &Value) -> JResult<bool> {
        match key {
            "id" => b.id = j_int(v)?,
            "name" => b.name = j_string(v)?,
            "type" => b.type_ = j_string(v)?,
            "url" => b.url = j_string(v)?,
            "format" => b.format = j_string(v)?,
            _ => return Ok(false),
        }
        Ok(true)
    }

    /// Applies a property of the concrete type (a `readerForUpdating` on the loaded entity).
    fn apply_variant(&mut self, key: &str, v: &Value) -> JResult<()> {
        match self {
            Lds::Base(_) => {}
            Lds::ImageWms(x) => {
                if apply_image(x, key, v)? {
                    return Ok(());
                }
            }
            Lds::TileWms(x) => {
                if apply_image(&mut x.image, key, v)? {
                    return Ok(());
                }
                match key {
                    "tileGrid" => {
                        x.tile_grid = if v.is_null() {
                            None
                        } else {
                            Some(Box::new(TileGrid::from_json(v, false)?))
                        }
                    }
                    "requestWithTiled" => x.request_with_tiled = j_bool(v)?,
                    _ => return Err(unknown(key)),
                }
            }
            Lds::Wfs(x) => match key {
                "version" => x.version = j_string(v)?,
                "typeName" => x.type_name = j_string(v)?,
                "typeNames" => x.type_names = j_string(v)?,
                _ => return Err(unknown(key)),
            },
            Lds::Wmts(x) => match key {
                "tileGrid" => {
                    x.tile_grid = if v.is_null() {
                        None
                    } else {
                        Some(Box::new(TileGrid::from_json(v, true)?))
                    }
                }
                "urls" => x.urls = j_list(v, |e| j_string(e))?,
                "wmtsLayer" => x.wmts_layer = j_string(v)?,
                "wmtsStyle" => x.wmts_style = j_string(v)?,
                "projection" => x.projection = j_string(v)?,
                "matrixSet" => x.matrix_set = j_string(v)?,
                "requestEncoding" => x.request_encoding = j_string(v)?,
                "capabilitiesUrl" => x.capabilities_url = j_string(v)?,
                _ => return Err(unknown(key)),
            },
            Lds::Xyz(x) => match key {
                "center" => x.center = point_from_json(v)?,
                "extent" => {
                    x.extent = if v.is_null() {
                        None
                    } else {
                        Some(Box::new(nested::<Extent>(v)?))
                    }
                }
                "resolutions" => x.resolutions = j_list(v, |e| j_f64(e))?,
                "tileSize" => x.tile_size = j_int(v)?,
                _ => return Err(unknown(key)),
            },
        }
        Ok(())
    }

    /// Writes an existing data source: the base row, the subtype row and the
    /// cascaded tile grid when it is part of this update.
    async fn update(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()> {
        let Some(id) = self.id() else {
            return dberr("inserting a layer data source is not supported");
        };
        {
            let b = self.base_ref();
            let rows = sqlx::query(
                "UPDATE layerdatasources SET modified = CASE WHEN $6 THEN now() ELSE modified END, \
                 format = $2, name = $3, type = $4, url = $5 WHERE id = $1",
            )
            .bind(id)
            .bind(&b.format)
            .bind(&b.name)
            .bind(&b.type_)
            .bind(&b.url)
            .bind(cx.touch_modified)
            .execute(&mut *cx.c)
            .await?
            .rows_affected();
            expect_one(rows, "layerdatasources")?;
        }
        match self {
            Lds::Base(_) => {}
            Lds::ImageWms(x) => update_image(cx, id, x).await?,
            Lds::TileWms(x) => {
                update_image(cx, id, &x.image).await?;
                let grid_id = match x.tile_grid.as_mut() {
                    Some(g) if t.has("tileGrid") => {
                        g.save(cx).await?;
                        g.id
                    }
                    Some(g) => g.id,
                    None => None,
                };
                let rows = sqlx::query(
                    "UPDATE tilewmslayerdatasources SET request_with_tiled = $2, tilegrid_id = $3 WHERE id = $1",
                )
                .bind(id)
                .bind(x.request_with_tiled)
                .bind(grid_id)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "tilewmslayerdatasources")?;
            }
            Lds::Wfs(x) => {
                let rows = sqlx::query(
                    "UPDATE wfslayerdatasources SET typename = $2, typenames = $3, version = $4 WHERE id = $1",
                )
                .bind(id)
                .bind(&x.type_name)
                .bind(&x.type_names)
                .bind(&x.version)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "wfslayerdatasources")?;
            }
            Lds::Wmts(x) => {
                let grid_id = match x.tile_grid.as_mut() {
                    Some(g) if t.has("tileGrid") => {
                        g.save(cx).await?;
                        g.id
                    }
                    Some(g) => g.id,
                    None => None,
                };
                let rows = sqlx::query(
                    "UPDATE wmtslayerdatasources SET capabilitiesurl = $2, matrixset = $3, projection = $4, \
                     requestencoding = $5, wmtslayer = $6, wmtsstyle = $7, tilegrid_id = $8 WHERE id = $1",
                )
                .bind(id)
                .bind(&x.capabilities_url)
                .bind(&x.matrix_set)
                .bind(&x.projection)
                .bind(&x.request_encoding)
                .bind(&x.wmts_layer)
                .bind(&x.wmts_style)
                .bind(grid_id)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "wmtslayerdatasources")?;
                if t.has("urls") {
                    sqlx::query("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1")
                        .bind(id)
                        .execute(&mut *cx.c)
                        .await?;
                    for u in x.urls.as_deref().unwrap_or(&[]).iter().flatten() {
                        sqlx::query("INSERT INTO wmtslayerdatasources_urls (wmtslayerdatasources_id, urls) VALUES ($1, $2)")
                            .bind(id)
                            .bind(u)
                            .execute(&mut *cx.c)
                            .await?;
                    }
                }
            }
            Lds::Xyz(x) => {
                let ext_id = match &x.extent {
                    None => None,
                    Some(e) => match e.id {
                        Some(eid) => Some(eid),
                        None => return dberr("transient extent"),
                    },
                };
                let (cx_, cy_) = match &x.center {
                    None => (None, None),
                    Some(p) => (Some(p.x), Some(p.y)),
                };
                let rows = sqlx::query(
                    "UPDATE xyzlayerdatasources SET center_x = $2, center_y = $3, tilesize = $4, extent_id = $5 \
                     WHERE id = $1",
                )
                .bind(id)
                .bind(cx_)
                .bind(cy_)
                .bind(x.tile_size)
                .bind(ext_id)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "xyzlayerdatasources")?;
                if t.has("resolutions") {
                    sqlx::query("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1")
                        .bind(id)
                        .execute(&mut *cx.c)
                        .await?;
                    for (idx, r) in x.resolutions.as_deref().unwrap_or(&[]).iter().enumerate() {
                        if let Some(r) = r {
                            sqlx::query(
                                "INSERT INTO xyzlayerdatasrc_resolution (xyzlayerdatasrc_id, resolution, idx) \
                                 VALUES ($1, $2, $3)",
                            )
                            .bind(id)
                            .bind(java_serialized_double(*r))
                            .bind(idx as i32)
                            .execute(&mut *cx.c)
                            .await?;
                        }
                    }
                }
            }
        }
        Ok(())
    }

    /// Cascade-free delete: subtype rows first, the base row next, then the
    /// tile grid of a WMTS source (its cascade ALL).
    async fn remove(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let Some(id) = self.id() else { return dberr("no id") };
        match self {
            Lds::Base(_) => {}
            Lds::ImageWms(_) => {
                delete_image_row(cx, id).await?;
            }
            Lds::TileWms(_) => {
                sqlx::query("DELETE FROM tilewmslayerdatasources WHERE id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
                delete_image_row(cx, id).await?;
            }
            Lds::Wfs(_) => {
                sqlx::query("DELETE FROM wfslayerdatasources WHERE id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
            }
            Lds::Wmts(_) => {
                sqlx::query("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
                sqlx::query("DELETE FROM wmtslayerdatasources WHERE id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
            }
            Lds::Xyz(_) => {
                sqlx::query("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
                sqlx::query("DELETE FROM xyzlayerdatasources WHERE id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
            }
        }
        delete_entity_perms(cx.c, id).await?;
        sqlx::query("DELETE FROM layerdatasources WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        if let Lds::Wmts(x) = self {
            if let Some(g) = &x.tile_grid {
                g.delete(cx).await?;
            }
        }
        Ok(())
    }

    /// Loads data sources (all, or by id) with their subtype and related objects.
    pub async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Lds>> {
        let ids: Option<Vec<i32>> = ids.map(|s| s.to_vec());
        let base_rows = sqlx::query(
            "SELECT id, name, type, url, format FROM layerdatasources \
             WHERE ($1::int4[] IS NULL OR id = ANY($1)) ORDER BY id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut bases: Vec<LdsBase> = Vec::with_capacity(base_rows.len());
        for r in base_rows {
            bases.push(LdsBase {
                id: Some(r.try_get("id")?),
                name: r.try_get("name")?,
                type_: r.try_get("type")?,
                url: r.try_get("url")?,
                format: r.try_get("format")?,
            });
        }

        let image_rows = sqlx::query(
            "SELECT id, customrequestpath, height, layernames, layerstyles, requestablebypath, version, width \
             FROM imagewmslayerdatasources WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut images: Vec<(i32, ImageWms)> = Vec::new();
        for r in image_rows {
            let id: i32 = r.try_get("id")?;
            images.push((
                id,
                ImageWms {
                    base: LdsBase::default(),
                    width: r.try_get("width")?,
                    height: r.try_get("height")?,
                    version: r.try_get("version")?,
                    layer_names: r.try_get("layernames")?,
                    layer_styles: r.try_get("layerstyles")?,
                    requestable_by_path: r.try_get("requestablebypath")?,
                    custom_request_path: r.try_get("customrequestpath")?,
                },
            ));
        }

        let tile_rows = sqlx::query(
            "SELECT id, request_with_tiled, tilegrid_id FROM tilewmslayerdatasources \
             WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut tiles: Vec<(i32, Option<bool>, Option<i32>)> = Vec::new();
        for r in tile_rows {
            tiles.push((r.try_get("id")?, r.try_get("request_with_tiled")?, r.try_get("tilegrid_id")?));
        }

        let wfs_rows = sqlx::query(
            "SELECT id, typename, typenames, version FROM wfslayerdatasources \
             WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut wfss: Vec<(i32, Wfs)> = Vec::new();
        for r in wfs_rows {
            wfss.push((
                r.try_get("id")?,
                Wfs {
                    base: LdsBase::default(),
                    type_name: r.try_get("typename")?,
                    type_names: r.try_get("typenames")?,
                    version: r.try_get("version")?,
                },
            ));
        }

        let wmts_rows = sqlx::query(
            "SELECT id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
             FROM wmtslayerdatasources WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut wmtss: Vec<(i32, Wmts, Option<i32>)> = Vec::new();
        for r in wmts_rows {
            wmtss.push((
                r.try_get("id")?,
                Wmts {
                    base: LdsBase::default(),
                    tile_grid: None,
                    urls: Some(Vec::new()),
                    wmts_layer: r.try_get("wmtslayer")?,
                    wmts_style: r.try_get("wmtsstyle")?,
                    projection: r.try_get("projection")?,
                    matrix_set: r.try_get("matrixset")?,
                    request_encoding: r.try_get("requestencoding")?,
                    capabilities_url: r.try_get("capabilitiesurl")?,
                },
                r.try_get("tilegrid_id")?,
            ));
        }
        let url_rows = sqlx::query(
            "SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls \
             WHERE ($1::int4[] IS NULL OR wmtslayerdatasources_id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for r in url_rows {
            let sid: i32 = r.try_get("wmtslayerdatasources_id")?;
            let url: Option<String> = r.try_get("urls")?;
            if let Some((_, w, _)) = wmtss.iter_mut().find(|x| x.0 == sid) {
                w.urls.get_or_insert_with(Vec::new).push(url);
            }
        }

        let xyz_rows = sqlx::query(
            "SELECT id, center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources \
             WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut xyzs: Vec<(i32, Xyz, Option<i32>)> = Vec::new();
        for r in xyz_rows {
            let cxv: Option<f64> = r.try_get("center_x")?;
            let cyv: Option<f64> = r.try_get("center_y")?;
            xyzs.push((
                r.try_get("id")?,
                Xyz {
                    base: LdsBase::default(),
                    center: if cxv.is_none() && cyv.is_none() {
                        None
                    } else {
                        Some(Point {
                            x: cxv.unwrap_or(0.0),
                            y: cyv.unwrap_or(0.0),
                        })
                    },
                    extent: None,
                    resolutions: Some(Vec::new()),
                    tile_size: r.try_get("tilesize")?,
                },
                r.try_get("extent_id")?,
            ));
        }
        let res_rows = sqlx::query(
            "SELECT xyzlayerdatasrc_id, resolution FROM xyzlayerdatasrc_resolution \
             WHERE ($1::int4[] IS NULL OR xyzlayerdatasrc_id = ANY($1)) ORDER BY idx",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for r in res_rows {
            let sid: i32 = r.try_get("xyzlayerdatasrc_id")?;
            let bytes: Option<Vec<u8>> = r.try_get("resolution")?;
            if let Some((_, x, _)) = xyzs.iter_mut().find(|x| x.0 == sid) {
                x.resolutions
                    .get_or_insert_with(Vec::new)
                    .push(bytes.as_deref().and_then(read_java_double));
            }
        }
        let ext_ids: Vec<i32> = xyzs.iter().filter_map(|x| x.2).collect();
        let exts = Extent::load_ids(c, &ext_ids).await?;
        for (_, x, eid) in xyzs.iter_mut() {
            x.extent = eid.and_then(|e| exts.iter().find(|x| x.id == Some(e)).cloned().map(Box::new));
        }

        let grid_ids: Vec<i32> = tiles
            .iter()
            .filter_map(|t| t.2)
            .chain(wmtss.iter().filter_map(|w| w.2))
            .collect();
        let grids = TileGrid::load_ids(c, &grid_ids).await?;

        let mut out = Vec::with_capacity(bases.len());
        for mut base in bases {
            let id = base.id.unwrap_or_default();
            let lds = if let Some((_, t, gid)) = tiles.iter().find(|t| t.0 == id) {
                let image = images
                    .iter()
                    .find(|x| x.0 == id)
                    .map(|x| x.1.clone())
                    .unwrap_or_default();
                let mut image = image;
                image.base = std::mem::take(&mut base);
                Lds::TileWms(TileWms {
                    image,
                    tile_grid: gid.and_then(|g| grids.iter().find(|x| x.id == Some(g)).cloned().map(Box::new)),
                    request_with_tiled: *t,
                })
            } else if let Some((_, img)) = images.iter().find(|x| x.0 == id) {
                let mut image = img.clone();
                image.base = base;
                Lds::ImageWms(image)
            } else if let Some((_, w)) = wfss.iter().find(|x| x.0 == id) {
                let mut w = w.clone();
                w.base = base;
                Lds::Wfs(w)
            } else if let Some((_, w, gid)) = wmtss.iter().find(|x| x.0 == id) {
                let mut w = w.clone();
                w.base = base;
                w.tile_grid = gid.and_then(|g| grids.iter().find(|x| x.id == Some(g)).cloned().map(Box::new));
                Lds::Wmts(w)
            } else if let Some((_, x, _)) = xyzs.iter().find(|x| x.0 == id) {
                let mut x = x.clone();
                x.base = base;
                Lds::Xyz(x)
            } else {
                Lds::Base(base)
            };
            out.push(lds);
        }
        Ok(out)
    }
}

fn apply_image(x: &mut ImageWms, key: &str, v: &Value) -> JResult<bool> {
    match key {
        "width" => x.width = j_int_prim(v)?,
        "height" => x.height = j_int_prim(v)?,
        "version" => x.version = j_string(v)?,
        "layerNames" => x.layer_names = j_string(v)?,
        "layerStyles" => x.layer_styles = j_string(v)?,
        "requestableByPath" => x.requestable_by_path = j_bool(v)?,
        "customRequestPath" => x.custom_request_path = j_string(v)?,
        _ => {
            if Lds::apply_common(&mut x.base, key, v)? {
                return Ok(true);
            }
            return Ok(false);
        }
    }
    Ok(true)
}

async fn update_image(cx: &mut Ctx<'_>, id: i32, x: &ImageWms) -> DbResult<()> {
    let rows = sqlx::query(
        "UPDATE imagewmslayerdatasources SET customrequestpath = $2, height = $3, layernames = $4, \
         layerstyles = $5, requestablebypath = $6, version = $7, width = $8 WHERE id = $1",
    )
    .bind(id)
    .bind(&x.custom_request_path)
    .bind(x.height)
    .bind(&x.layer_names)
    .bind(&x.layer_styles)
    .bind(x.requestable_by_path)
    .bind(&x.version)
    .bind(x.width)
    .execute(&mut *cx.c)
    .await?
    .rows_affected();
    expect_one(rows, "imagewmslayerdatasources")
}

async fn delete_image_row(cx: &mut Ctx<'_>, id: i32) -> DbResult<()> {
    sqlx::query("DELETE FROM imagewmslayerdatasources WHERE id = $1")
        .bind(id)
        .execute(&mut *cx.c)
        .await?;
    Ok(())
}

/// `java.lang.Double` as Hibernate's serialisable type stores it: the Java
/// serialisation stream of a Double object (constant prefix + big-endian value).
pub fn java_serialized_double(d: f64) -> Vec<u8> {
    const PREFIX: &[u8] = &[
        0xAC, 0xED, 0x00, 0x05, 0x73, 0x72, 0x00, 0x10, b'j', b'a', b'v', b'a', b'.', b'l', b'a', b'n', b'g',
        b'.', b'D', b'o', b'u', b'b', b'l', b'e', 0x80, 0xB3, 0xC2, 0x4A, 0x6A, 0x29, 0xFB, 0x04, 0x02, 0x00,
        0x01, 0x44, 0x00, 0x05, b'v', b'a', b'l', b'u', b'e', 0x78, 0x72, 0x00, 0x10, b'j', b'a', b'v', b'a',
        b'.', b'l', b'a', b'n', b'g', b'.', b'N', b'u', b'm', b'b', b'e', b'r', 0x86, 0xAC, 0x95, 0x1D, 0x0B,
        0x94, 0xE0, 0x8B, 0x02, 0x00, 0x00, 0x78, 0x70,
    ];
    let mut v = PREFIX.to_vec();
    v.extend_from_slice(&d.to_be_bytes());
    v
}

/// Reads a stored Java-serialised Double (its value is the last 8 bytes).
pub fn read_java_double(bytes: &[u8]) -> Option<f64> {
    if bytes.len() < 8 {
        return None;
    }
    let mut b = [0u8; 8];
    b.copy_from_slice(&bytes[bytes.len() - 8..]);
    Some(f64::from_be_bytes(b))
}

#[async_trait]
impl Res for Lds {
    const ENT: Ent = Ent::Lds;
    const FIELDS: &'static [(&'static str, FT)] = &[
        ("id", FT::Int),
        ("name", FT::Str),
        ("type", FT::Str),
        ("url", FT::Str),
        ("format", FT::Str),
    ];

    fn new_default() -> Self {
        Lds::default()
    }

    fn id(&self) -> Option<i32> {
        Lds::id(self)
    }

    fn apply_key(&mut self, key: &str, v: &Value) -> JResult<()> {
        if Lds::apply_common(self.base_mut(), key, v)? {
            return Ok(());
        }
        if ignored_key(key) {
            return Ok(());
        }
        self.apply_variant(key, v)
    }

    async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Self>> {
        Lds::load(c, ids).await
    }

    async fn write(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()> {
        self.update(cx, t).await
    }

    async fn delete(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        self.remove(cx).await
    }
}

#[allow(dead_code)]
fn _bool_prim_is_used(v: &Value) -> JResult<bool> {
    j_bool_prim(v)
}

#[allow(dead_code)]
fn _row_used(r: &sqlx::postgres::PgRow) -> Option<i32> {
    r.try_get("id").ok()
}

tool_use_result.content:
//! `LayerDataSource` and its subtypes (JOINED inheritance, no discriminator:
//! the subtype is the table that holds the row).

use async_trait::async_trait;
use serde::{Serialize, Serializer};
use serde_json::Value;
use sqlx::{PgConnection, Row};

use crate::acl::Ent;
use crate::db::{dberr, expect_one, Ctx, DbResult, Touched};
use crate::jv::{j_bool, j_f64, j_int, j_int_prim, j_list, j_string, j_bool_prim, JResult};
use crate::model::grid::{point_from_json, Extent, Point, TileGrid};
use crate::model::user::delete_entity_perms;
use crate::res::{ignored_key, nested, unknown, FT, Res};

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct LdsBase {
    pub id: Option<i32>,
    pub name: Option<String>,
    #[serde(rename = "type")]
    pub type_: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
}

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct ImageWms {
    #[serde(flatten)]
    pub base: LdsBase,
    pub width: i32,
    pub height: i32,
    pub version: Option<String>,
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
}

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct TileWms {
    #[serde(flatten)]
    pub image: ImageWms,
    pub tile_grid: Option<Box<TileGrid>>,
    pub request_with_tiled: Option<bool>,
}

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct Wfs {
    #[serde(flatten)]
    pub base: LdsBase,
    pub version: Option<String>,
    pub type_name: Option<String>,
    pub type_names: Option<String>,
}

#[derive(Serialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct Wmts {
    #[serde(flatten)]
    pub base: LdsBase,
    pub tile_grid: Option<Box<TileGrid>>,
    pub urls: Option<Vec<Option<String>>>,
    pub wmts_layer: Option<String>,
    pub wmts_style: Option<String>,
    pub projection: Option<String>,
    pub matrix_set: Option<String>,
    pub request_encoding: Option<String>,
    pub capabilities_url: Option<String>,
}

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct Xyz {
    #[serde(flatten)]
    pub base: LdsBase,
    pub center: Option<Point>,
    pub extent: Option<Box<Extent>>,
    pub resolutions: Option<Vec<Option<f64>>>,
    pub tile_size: Option<i32>,
}

#[derive(Clone, Debug)]
pub enum Lds {
    Base(LdsBase),
    ImageWms(ImageWms),
    TileWms(TileWms),
    Wfs(Wfs),
    Wmts(Wmts),
    Xyz(Xyz),
}

impl Serialize for Lds {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            Lds::Base(x) => x.serialize(s),
            Lds::ImageWms(x) => x.serialize(s),
            Lds::TileWms(x) => x.serialize(s),
            Lds::Wfs(x) => x.serialize(s),
            Lds::Wmts(x) => x.serialize(s),
            Lds::Xyz(x) => x.serialize(s),
        }
    }
}

impl Default for Xyz {
    fn default() -> Self {
        Xyz {
            base: LdsBase::default(),
            center: None,
            extent: None,
            resolutions: Some(Vec::new()),
            tile_size: None,
        }
    }
}

impl Default for TileWms {
    fn default() -> Self {
        TileWms {
            image: ImageWms::default(),
            tile_grid: None,
            request_with_tiled: Some(true),
        }
    }
}

impl Default for Lds {
    fn default() -> Self {
        Lds::Base(LdsBase::default())
    }
}

impl Lds {
    pub fn id(&self) -> Option<i32> {
        self.base_ref().id
    }

    fn base_ref(&self) -> &LdsBase {
        match self {
            Lds::Base(b) => b,
            Lds::ImageWms(x) => &x.base,
            Lds::TileWms(x) => &x.image.base,
            Lds::Wfs(x) => &x.base,
            Lds::Wmts(x) => &x.base,
            Lds::Xyz(x) => &x.base,
        }
    }

    fn base_mut(&mut self) -> &mut LdsBase {
        match self {
            Lds::Base(b) => b,
            Lds::ImageWms(x) => &mut x.base,
            Lds::TileWms(x) => &mut x.image.base,
            Lds::Wfs(x) => &mut x.base,
            Lds::Wmts(x) => &mut x.base,
            Lds::Xyz(x) => &mut x.base,
        }
    }

    fn apply_common(b: &mut LdsBase, key: &str, v: &Value) -> JResult<bool> {
        match key {
            "id" => b.id = j_int(v)?,
            "name" => b.name = j_string(v)?,
            "type" => b.type_ = j_string(v)?,
            "url" => b.url = j_string(v)?,
            "format" => b.format = j_string(v)?,
            _ => return Ok(false),
        }
        Ok(true)
    }

    /// Applies a property of the concrete type (a `readerForUpdating` on the loaded entity).
    fn apply_variant(&mut self, key: &str, v: &Value) -> JResult<()> {
        match self {
            Lds::Base(_) => {}
            Lds::ImageWms(x) => {
                if apply_image(x, key, v)? {
                    return Ok(());
                }
            }
            Lds::TileWms(x) => {
                if apply_image(&mut x.image, key, v)? {
                    return Ok(());
                }
                match key {
                    "tileGrid" => {
                        x.tile_grid = if v.is_null() {
                            None
                        } else {
                            Some(Box::new(TileGrid::from_json(v, false)?))
                        }
                    }
                    "requestWithTiled" => x.request_with_tiled = j_bool(v)?,
                    _ => return Err(unknown(key)),
                }
            }
            Lds::Wfs(x) => match key {
                "version" => x.version = j_string(v)?,
                "typeName" => x.type_name = j_string(v)?,
                "typeNames" => x.type_names = j_string(v)?,
                _ => return Err(unknown(key)),
            },
            Lds::Wmts(x) => match key {
                "tileGrid" => {
                    x.tile_grid = if v.is_null() {
                        None
                    } else {
                        Some(Box::new(TileGrid::from_json(v, true)?))
                    }
                }
                "urls" => x.urls = j_list(v, |e| j_string(e))?,
                "wmtsLayer" => x.wmts_layer = j_string(v)?,
                "wmtsStyle" => x.wmts_style = j_string(v)?,
                "projection" => x.projection = j_string(v)?,
                "matrixSet" => x.matrix_set = j_string(v)?,
                "requestEncoding" => x.request_encoding = j_string(v)?,
                "capabilitiesUrl" => x.capabilities_url = j_string(v)?,
                _ => return Err(unknown(key)),
            },
            Lds::Xyz(x) => match key {
                "center" => x.center = point_from_json(v)?,
                "extent" => {
                    x.extent = if v.is_null() {
                        None
                    } else {
                        Some(Box::new(nested::<Extent>(v)?))
                    }
                }
                "resolutions" => x.resolutions = j_list(v, |e| j_f64(e))?,
                "tileSize" => x.tile_size = j_int(v)?,
                _ => return Err(unknown(key)),
            },
        }
        Ok(())
    }

    /// Writes an existing data source: the base row, the subtype row and the
    /// cascaded tile grid when it is part of this update.
    async fn update(&mut self, cx: &mut Ctx<'_>, t: &Touched) -> DbResult<()> {
        let Some(id) = self.id() else {
            return dberr("inserting a layer data source is not supported");
        };
        {
            let b = self.base_ref();
            let rows = sqlx::query(
                "UPDATE layerdatasources SET modified = CASE WHEN $6 THEN now() ELSE modified END, \
                 format = $2, name = $3, type = $4, url = $5 WHERE id = $1",
            )
            .bind(id)
            .bind(&b.format)
            .bind(&b.name)
            .bind(&b.type_)
            .bind(&b.url)
            .bind(cx.touch_modified)
            .execute(&mut *cx.c)
            .await?
            .rows_affected();
            expect_one(rows, "layerdatasources")?;
        }
        match self {
            Lds::Base(_) => {}
            Lds::ImageWms(x) => update_image(cx, id, x).await?,
            Lds::TileWms(x) => {
                update_image(cx, id, &x.image).await?;
                let grid_id = match x.tile_grid.as_mut() {
                    Some(g) if t.has("tileGrid") => {
                        g.save(cx).await?;
                        g.id
                    }
                    Some(g) => g.id,
                    None => None,
                };
                let rows = sqlx::query(
                    "UPDATE tilewmslayerdatasources SET request_with_tiled = $2, tilegrid_id = $3 WHERE id = $1",
                )
                .bind(id)
                .bind(x.request_with_tiled)
                .bind(grid_id)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "tilewmslayerdatasources")?;
            }
            Lds::Wfs(x) => {
                let rows = sqlx::query(
                    "UPDATE wfslayerdatasources SET typename = $2, typenames = $3, version = $4 WHERE id = $1",
                )
                .bind(id)
                .bind(&x.type_name)
                .bind(&x.type_names)
                .bind(&x.version)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "wfslayerdatasources")?;
            }
            Lds::Wmts(x) => {
                let grid_id = match x.tile_grid.as_mut() {
                    Some(g) if t.has("tileGrid") => {
                        g.save(cx).await?;
                        g.id
                    }
                    Some(g) => g.id,
                    None => None,
                };
                let rows = sqlx::query(
                    "UPDATE wmtslayerdatasources SET capabilitiesurl = $2, matrixset = $3, projection = $4, \
                     requestencoding = $5, wmtslayer = $6, wmtsstyle = $7, tilegrid_id = $8 WHERE id = $1",
                )
                .bind(id)
                .bind(&x.capabilities_url)
                .bind(&x.matrix_set)
                .bind(&x.projection)
                .bind(&x.request_encoding)
                .bind(&x.wmts_layer)
                .bind(&x.wmts_style)
                .bind(grid_id)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "wmtslayerdatasources")?;
                if t.has("urls") {
                    sqlx::query("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1")
                        .bind(id)
                        .execute(&mut *cx.c)
                        .await?;
                    for u in x.urls.as_deref().unwrap_or(&[]).iter().flatten() {
                        sqlx::query("INSERT INTO wmtslayerdatasources_urls (wmtslayerdatasources_id, urls) VALUES ($1, $2)")
                            .bind(id)
                            .bind(u)
                            .execute(&mut *cx.c)
                            .await?;
                    }
                }
            }
            Lds::Xyz(x) => {
                let ext_id = match &x.extent {
                    None => None,
                    Some(e) => match e.id {
                        Some(eid) => Some(eid),
                        None => return dberr("transient extent"),
                    },
                };
                let (cx_, cy_) = match &x.center {
                    None => (None, None),
                    Some(p) => (Some(p.x), Some(p.y)),
                };
                let rows = sqlx::query(
                    "UPDATE xyzlayerdatasources SET center_x = $2, center_y = $3, tilesize = $4, extent_id = $5 \
                     WHERE id = $1",
                )
                .bind(id)
                .bind(cx_)
                .bind(cy_)
                .bind(x.tile_size)
                .bind(ext_id)
                .execute(&mut *cx.c)
                .await?
                .rows_affected();
                expect_one(rows, "xyzlayerdatasources")?;
                if t.has("resolutions") {
                    sqlx::query("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1")
                        .bind(id)
                        .execute(&mut *cx.c)
                        .await?;
                    for (idx, r) in x.resolutions.as_deref().unwrap_or(&[]).iter().enumerate() {
                        if let Some(r) = r {
                            sqlx::query(
                                "INSERT INTO xyzlayerdatasrc_resolution (xyzlayerdatasrc_id, resolution, idx) \
                                 VALUES ($1, $2, $3)",
                            )
                            .bind(id)
                            .bind(java_serialized_double(*r))
                            .bind(idx as i32)
                            .execute(&mut *cx.c)
                            .await?;
                        }
                    }
                }
            }
        }
        Ok(())
    }

    /// Cascade-free delete: subtype rows first, the base row next, then the
    /// tile grid of a WMTS source (its cascade ALL).
    async fn remove(&self, cx: &mut Ctx<'_>) -> DbResult<()> {
        let Some(id) = self.id() else { return dberr("no id") };
        match self {
            Lds::Base(_) => {}
            Lds::ImageWms(_) => {
                delete_image_row(cx, id).await?;
            }
            Lds::TileWms(_) => {
                sqlx::query("DELETE FROM tilewmslayerdatasources WHERE id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
                delete_image_row(cx, id).await?;
            }
            Lds::Wfs(_) => {
                sqlx::query("DELETE FROM wfslayerdatasources WHERE id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
            }
            Lds::Wmts(_) => {
                sqlx::query("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
                sqlx::query("DELETE FROM wmtslayerdatasources WHERE id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
            }
            Lds::Xyz(_) => {
                sqlx::query("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
                sqlx::query("DELETE FROM xyzlayerdatasources WHERE id = $1")
                    .bind(id)
                    .execute(&mut *cx.c)
                    .await?;
            }
        }
        delete_entity_perms(cx.c, id).await?;
        sqlx::query("DELETE FROM layerdatasources WHERE id = $1")
            .bind(id)
            .execute(&mut *cx.c)
            .await?;
        if let Lds::Wmts(x) = self {
            if let Some(g) = &x.tile_grid {
                g.delete(cx).await?;
            }
        }
        Ok(())
    }

    /// Loads data sources (all, or by id) with their subtype and related objects.
    pub async fn load(c: &mut PgConnection, ids: Option<&[i32]>) -> DbResult<Vec<Lds>> {
        let ids: Option<Vec<i32>> = ids.map(|s| s.to_vec());
        let base_rows = sqlx::query(
            "SELECT id, name, type, url, format FROM layerdatasources \
             WHERE ($1::int4[] IS NULL OR id = ANY($1)) ORDER BY id",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut bases: Vec<LdsBase> = Vec::with_capacity(base_rows.len());
        for r in base_rows {
            bases.push(LdsBase {
                id: Some(r.try_get("id")?),
                name: r.try_get("name")?,
                type_: r.try_get("type")?,
                url: r.try_get("url")?,
                format: r.try_get("format")?,
            });
        }

        let image_rows = sqlx::query(
            "SELECT id, customrequestpath, height, layernames, layerstyles, requestablebypath, version, width \
             FROM imagewmslayerdatasources WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut images: Vec<(i32, ImageWms)> = Vec::new();
        for r in image_rows {
            let id: i32 = r.try_get("id")?;
            images.push((
                id,
                ImageWms {
                    base: LdsBase::default(),
                    width: r.try_get("width")?,
                    height: r.try_get("height")?,
                    version: r.try_get("version")?,
                    layer_names: r.try_get("layernames")?,
                    layer_styles: r.try_get("layerstyles")?,
                    requestable_by_path: r.try_get("requestablebypath")?,
                    custom_request_path: r.try_get("customrequestpath")?,
                },
            ));
        }

        let tile_rows = sqlx::query(
            "SELECT id, request_with_tiled, tilegrid_id FROM tilewmslayerdatasources \
             WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut tiles: Vec<(i32, Option<bool>, Option<i32>)> = Vec::new();
        for r in tile_rows {
            tiles.push((r.try_get("id")?, r.try_get("request_with_tiled")?, r.try_get("tilegrid_id")?));
        }

        let wfs_rows = sqlx::query(
            "SELECT id, typename, typenames, version FROM wfslayerdatasources \
             WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut wfss: Vec<(i32, Wfs)> = Vec::new();
        for r in wfs_rows {
            wfss.push((
                r.try_get("id")?,
                Wfs {
                    base: LdsBase::default(),
                    type_name: r.try_get("typename")?,
                    type_names: r.try_get("typenames")?,
                    version: r.try_get("version")?,
                },
            ));
        }

        let wmts_rows = sqlx::query(
            "SELECT id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
             FROM wmtslayerdatasources WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut wmtss: Vec<(i32, Wmts, Option<i32>)> = Vec::new();
        for r in wmts_rows {
            wmtss.push((
                r.try_get("id")?,
                Wmts {
                    base: LdsBase::default(),
                    tile_grid: None,
                    urls: Some(Vec::new()),
                    wmts_layer: r.try_get("wmtslayer")?,
                    wmts_style: r.try_get("wmtsstyle")?,
                    projection: r.try_get("projection")?,
                    matrix_set: r.try_get("matrixset")?,
                    request_encoding: r.try_get("requestencoding")?,
                    capabilities_url: r.try_get("capabilitiesurl")?,
                },
                r.try_get("tilegrid_id")?,
            ));
        }
        let url_rows = sqlx::query(
            "SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls \
             WHERE ($1::int4[] IS NULL OR wmtslayerdatasources_id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for r in url_rows {
            let sid: i32 = r.try_get("wmtslayerdatasources_id")?;
            let url: Option<String> = r.try_get("urls")?;
            if let Some((_, w, _)) = wmtss.iter_mut().find(|x| x.0 == sid) {
                w.urls.get_or_insert_with(Vec::new).push(url);
            }
        }

        let xyz_rows = sqlx::query(
            "SELECT id, center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources \
             WHERE ($1::int4[] IS NULL OR id = ANY($1))",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        let mut xyzs: Vec<(i32, Xyz, Option<i32>)> = Vec::new();
        for r in xyz_rows {
            let cxv: Option<f64> = r.try_get("center_x")?;
            let cyv: Option<f64> = r.try_get("center_y")?;
            xyzs.push((
                r.try_get("id")?,
                Xyz {
                    base: LdsBase::default(),
                    center: if cxv.is_none() && cyv.is_none() {
                        None
                    } else {
                        Some(Point {
                            x: cxv.unwrap_or(0.0),
                            y: cyv.unwrap_or(0.0),
                        })
                    },
                    extent: None,
                    resolutions: Some(Vec::new()),
                    tile_size: r.try_get("tilesize")?,
                },
                r.try_get("extent_id")?,
            ));
        }
        let res_rows = sqlx::query(
            "SELECT xyzlayerdatasrc_id, resolution FROM xyzlayerdatasrc_resolution \
             WHERE ($1::int4[] IS NULL OR xyzlayerdatasrc_id = ANY($1)) ORDER BY idx",
        )
        .bind(&ids)
        .fetch_all(&mut *c)
        .await?;
        for r in res_rows {
            let sid: i32 = r.try_get("xyzlayerdatasrc_id")?;
            let bytes: Option<Vec<u8>> = r.try_get("resolution")?;
            if let Some((_, x, _)) = xyzs.iter_mut().find(|x| x.0 == sid) {
                x.resolutions
                    .get_or_insert_with(Vec::new)
                    .push(bytes.as_deref().and_then(read_java_double));
            }
        }
        let ext_ids: Vec<i32> = xyzs.iter().filter_map(|x| x.2).collect();
        let exts = Extent::load_ids(c, &ext_ids).await?;
        for (_, x, eid) in xyzs.iter_mut() {
            x.extent = eid.and_then(|e| exts.iter().find(|x| x.id == Some(e)).cloned().map(Box::new));
        }

        let grid_ids: Vec<i32> = tiles
            .iter()
            .filter_map(|t| t.2)
            .chain(wmtss.iter().filter_map(|w| w.2))
            .collect();
        let grids = TileGrid::load_ids(c, &grid_ids).await?;

        let mut out = Vec::with_capacity(bases.len());
        for mut base in bases {
            let id = base.id.unwrap_or_default();
            let lds = if let Some((_, t, gid)) = tiles.iter().find(|t| t.0 == id) {
                let image = images
                    .iter()
                    .find(|x| x.0 == id)
                    .map(|x| x.1.clone())
                    .unwrap_or_default();
                let mut image = image;
                image.base = std::mem::take(&mut base);
                Lds::TileWms(TileWms {
                    image,
                    tile_grid: gid.and_then(|g| grids.iter().find(|x| x.id == Some(g)).cloned().map(Box::new)),
                    request_with_tiled: *t,
                })
            } else if let Some((_, img)) = images.iter().find(|x| x.0 == id) {
                let mut image = img.clone();
                image.base = base;
                Lds::ImageWms(image)
            } else if let Some((_, w)) = wfss.iter().find(|x| x.0 == id) {
                let mut w = w.clone();
                w.base = base;
                Lds::Wfs(w)
            } else if let Some((_, w, gid)) = wmtss.iter().find(|x| x.0 == id) {
                let mut w = w.clone();
                w.base = base;
                w.tile_grid = gid.and_then(|g| grids.iter().find(|x| x.id == Some(g)).cloned().map(Box::new));
                Lds::Wmts(w)
            } else if let Some((_, x, _)) = xyzs.iter().find(|x| x.0 == id) {
                let mut x = x.clone();
                x.base = base;
                Lds::Xyz(x)
            } else {
                Lds::Base(base)
            };
            out.push(lds);
        }
        Ok(out)
    }
}

fn apply_image(x: &mut ImageWms, key: &str, v: &Value) -> JResult<bool> {
    match key {
        "width" => x.width = j_int_prim(v)?,
        "height" => x.height = j_int_prim(v)?,
        "version" => x.version = j_string(v)?,
        "layerNames" => x.layer_names = j_string(v)?,
        "layerStyles" => x.layer_styles = j_string(v)?,
        "requestableByPath" => x.requestable_by_path = j_bool(v)?,
        "customRequestPath" => x.custom_request_path = j_string(v)?,
        _ => {
            if Lds::apply_common(&mut x.base, key, v)? {
                return Ok(true);
            }
            return Ok(false);
        }
    }
    Ok(true)
}

async fn update_image(cx: &mut Ctx<'_>, id: i32, x: &ImageWms) -> DbResult<()> {
    let rows = sqlx::query(
        "UPDATE imagewmslayerdatasources SET customrequestpath = $2, height = $3, layernames = $4, \
         layerstyles = $5, requestablebypath = $6, version = $7, width = $8 WHERE id = $1",
    )
    .bind(id)
    .bind(&x.custom_request_path)
    .bind(x.height)
    .bind(&x.layer_names)
    .bind(&x.layer_styles)
    .bind(x.requestable_by_path)
    .bind(&x.version)
    .bind(x.width)
    .execute(&mut *cx.c)
    .await?
    .rows_affected();
    expect_one(rows, "imagewmslayerdatasources")
}

async fn delete_image_row(cx: &mut Ctx<'_>, id: i32) -> DbResult<()> {
    sqlx::query("DELETE FROM imagewmslayerdatasources WHERE id = $1")
        .bind(id)
        .execute(&mut *cx.c)
        .await?;
    Ok(())
}

/// `java.lang.Double` as Hibernate's serialisable type stores it: the Java
/// serialisation stream of a Double object (constant prefix + big-endian value).
pub fn java_serialized_double(d: f64) -> Vec<u8> {
    const PREFIX: &[u8] = &[
        0xAC, 0xED, 0x00, 0x05, 0x73, 0x72, 0x00, 0x10, b'j', b'a', b'v', b'a', b'.', b'l', b'a', b'n', b'g',
        b'.', b'D', b'o', b'u', b'b', b'l', b'e', 0x80, 0xB3, 0xC2, 0x4A, 0x6A, 0x29, 0xFB, 0x04, 0x02, 0x00,
