    const ENT: Ent = Ent::Lds;
    const FIELDS: &'static [(&'static str, FT)] = &[
        ("id", FT::Int),
        ("name", FT::Str),
        ("type", FT::Str),
        ("url", FT::Str),
        ("format", FT::Str),
    ];

