//! The generic REST endpoints of `AbstractRestController` and the
//! `AbstractCrudService` permission filters, for any `Res` resource.

use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use serde::Serialize;
use serde_json::Value;
use sqlx::{PgPool, Postgres, Transaction};

use crate::acl::{allowed, allowed_ids, restricted_readable, Ent, Perm, Principal};
use crate::db::{Ctx, Touched};
use crate::jv::{as_int_lenient, parse_first};
use crate::model::user::{groups_of, Role, User, UserGroup};
use crate::res::{filter_criteria, matches_criteria, project, restrict_fields, Res};

pub fn json_response<T: Serialize + ?Sized>(status: StatusCode, body: &T) -> Response {
    match serde_json::to_vec(body) {
        Ok(bytes) => (
            status,
            [(axum::http::header::CONTENT_TYPE, "application/json;charset=UTF-8")],
            bytes,
        )
            .into_response(),
        Err(_) => status_only(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

pub fn status_only(status: StatusCode) -> Response {
    status.into_response()
}

/// Any database failure on a read path: the original answers 500.
fn server_error() -> Response {
    status_only(StatusCode::INTERNAL_SERVER_ERROR)
}

async fn begin(pool: &PgPool) -> Result<Transaction<'static, Postgres>, Response> {
    pool.begin().await.map_err(|_| server_error())
}

/// `findAll` / `findAllRestricted` / `findBySimpleFilter`.
pub async fn list<R: Res>(pool: &PgPool, p: &Principal, query: &[(String, String)], filtered: bool) -> Response {
    let criteria = if filtered {
        let c = filter_criteria::<R>(query);
        if c.is_empty() {
            return json_response(StatusCode::OK, &Vec::<Value>::new());
        }
        c
    } else {
        Vec::new()
    };
    let restrict = restrict_fields::<R>(query);
    let mut tx = match begin(pool).await {
        Ok(t) => t,
        Err(r) => return r,
    };
    let rows = match R::load(&mut tx, None).await {
        Ok(r) => r,
        Err(_) => return server_error(),
    };
    let mut values: Vec<Value> = Vec::with_capacity(rows.len());
    for r in &rows {
        let v = match serde_json::to_value(r) {
            Ok(v) => v,
            Err(_) => return server_error(),
        };
        if matches_criteria(&v, &criteria) {
            values.push(v);
        }
    }
    let out: Vec<Value> = match restrict {
        Some(fields) => {
            // a projected LayerDataSource cannot be instantiated (abstract class)
            if R::ENT == Ent::Lds && !values.is_empty() {
                return server_error();
            }
            if !restricted_readable(p, R::ENT) {
                Vec::new()
            } else {
                let default = serde_json::to_value(R::new_default()).unwrap_or(Value::Null);
                values
                    .iter()
                    .map(|v| project(v, &default, &fields))
                    .collect()
            }
        }
        None => {
            let ids: Vec<i32> = values.iter().filter_map(|v| v.get("id").and_then(|x| x.as_i64()).map(|x| x as i32)).collect();
            let ok = match allowed_ids(&mut tx, p, R::ENT, &ids, Perm::Read).await {
                Ok(s) => s,
                Err(_) => return server_error(),
            };
            values
                .into_iter()
                .filter(|v| {
                    v.get("id")
                        .and_then(|x| x.as_i64())
                        .map(|x| ok.contains(&(x as i32)))
                        .unwrap_or(false)
                })
                .collect()
        }
    };
    let _ = tx.rollback().await;
    json_response(StatusCode::OK, &out)
}

/// `findById` (READ required, otherwise 404).
pub async fn get_one<R: Res>(pool: &PgPool, p: &Principal, id: i32) -> Response {
    let mut tx = match begin(pool).await {
        Ok(t) => t,
        Err(r) => return r,
    };
    let rows = match R::load(&mut tx, Some(&[id])).await {
        Ok(r) => r,
        Err(_) => return server_error(),
    };
    let Some(entity) = rows.into_iter().next() else {
        return status_only(StatusCode::NOT_FOUND);
    };
    match allowed(&mut tx, p, R::ENT, id, Perm::Read).await {
        Ok(true) => {}
        Ok(false) => return status_only(StatusCode::NOT_FOUND),
        Err(_) => return server_error(),
    }
    let _ = tx.rollback().await;
    json_response(StatusCode::OK, &entity)
}

/// The body of a POST/PUT: a JSON object, the first value of the document.
fn body_object(body: &[u8]) -> Option<serde_json::Map<String, Value>> {
    match parse_first(body) {
        Ok(Value::Object(o)) => Some(o),
        _ => None,
    }
}

/// `AbstractRestController.save`.
pub async fn create<R: Res>(pool: &PgPool, p: &Principal, body: &[u8]) -> Response {
    // LayerDataSource cannot be built from JSON, so creating one is always refused.
    if R::ENT == Ent::Lds {
        return status_only(StatusCode::BAD_REQUEST);
    }
    let Some(obj) = body_object(body) else {
        return status_only(StatusCode::BAD_REQUEST);
    };
    let mut entity = R::new_default();
    for (k, v) in &obj {
        if entity.apply_key(k, v).is_err() {
            return status_only(StatusCode::BAD_REQUEST);
        }
    }
    if entity.id().is_some() {
        return status_only(StatusCode::BAD_REQUEST);
    }
    // CREATE: a new entity has no permission collections, only the super admin may create
    if !p.super_admin {
        return status_only(StatusCode::BAD_REQUEST);
    }
    let mut tx = match begin(pool).await {
        Ok(t) => t,
        Err(_) => return status_only(StatusCode::BAD_REQUEST),
    };
    let res = {
        let mut cx = Ctx {
            c: &mut tx,
            pool,
            touch_modified: true,
        };
        entity.write(&mut cx, &Touched::All).await
    };
    if res.is_err() {
        let _ = tx.rollback().await;
        return status_only(StatusCode::BAD_REQUEST);
    }
    if tx.commit().await.is_err() {
        return status_only(StatusCode::BAD_REQUEST);
    }
    json_response(StatusCode::CREATED, &entity)
}

/// `AbstractRestController.update` with `updatePartialWithJsonNode`.
///
/// Properties are applied in document order. A JSON-level failure stops the
/// application, but what was already applied is committed (the checked
/// exception does not roll the transaction back); the response is 404 anyway.
pub async fn update<R: Res>(pool: &PgPool, p: &Principal, id: i32, body: &[u8]) -> Response {
    if body.iter().all(|b| b.is_ascii_whitespace()) {
        return status_only(StatusCode::BAD_REQUEST);
    }
    let value = match parse_first(body) {
        Ok(v) => v,
        Err(_) => return status_only(StatusCode::NOT_FOUND),
    };
    let Some(obj) = value.as_object() else {
        return status_only(StatusCode::BAD_REQUEST);
    };
    let Some(id_node) = obj.get("id") else {
        return status_only(StatusCode::BAD_REQUEST);
    };
    if as_int_lenient(id_node) != id {
        return status_only(StatusCode::BAD_REQUEST);
    }
    let mut tx = match begin(pool).await {
        Ok(t) => t,
        Err(_) => return status_only(StatusCode::NOT_FOUND),
    };
    let rows = match R::load(&mut tx, Some(&[id])).await {
        Ok(r) => r,
        Err(_) => return status_only(StatusCode::NOT_FOUND),
    };
    let Some(mut entity) = rows.into_iter().next() else {
        return status_only(StatusCode::NOT_FOUND);
    };
    match allowed(&mut tx, p, R::ENT, id, Perm::Read).await {
        Ok(true) => {}
        _ => return status_only(StatusCode::NOT_FOUND),
    }
    match allowed(&mut tx, p, R::ENT, id, Perm::Update).await {
        Ok(true) => {}
        _ => return status_only(StatusCode::NOT_FOUND),
    }

    let mut touched = Touched::none();
    let mut partial = false;
    for (k, v) in obj {
        match entity.apply_key(k, v) {
            Ok(()) => touched.add(k),
            Err(_) => {
                partial = true;
                break;
            }
        }
    }
    let written = {
        let mut cx = Ctx {
            c: &mut tx,
            pool,
            touch_modified: !partial,
        };
        entity.write(&mut cx, &touched).await
    };
    match written {
        Ok(()) => {
            if tx.commit().await.is_err() {
                return status_only(StatusCode::NOT_FOUND);
            }
            if partial {
                status_only(StatusCode::NOT_FOUND)
            } else {
                json_response(StatusCode::OK, &entity)
            }
        }
        Err(_) => {
            let _ = tx.rollback().await;
            status_only(StatusCode::NOT_FOUND)
        }
    }
}

/// `AbstractRestController.delete`.
pub async fn delete<R: Res>(pool: &PgPool, p: &Principal, id: i32) -> Response {
    let mut tx = match begin(pool).await {
        Ok(t) => t,
        Err(_) => return status_only(StatusCode::NOT_FOUND),
    };
    let rows = match R::load(&mut tx, Some(&[id])).await {
        Ok(r) => r,
        Err(_) => return status_only(StatusCode::NOT_FOUND),
    };
    let Some(entity) = rows.into_iter().next() else {
        return status_only(StatusCode::NOT_FOUND);
    };
    match allowed(&mut tx, p, R::ENT, id, Perm::Read).await {
        Ok(true) => {}
        _ => return status_only(StatusCode::NOT_FOUND),
    }
    match allowed(&mut tx, p, R::ENT, id, Perm::Delete).await {
        Ok(true) => {}
        _ => return status_only(StatusCode::NOT_FOUND),
    }
    let res = {
        let mut cx = Ctx {
            c: &mut tx,
            pool,
            touch_modified: true,
        };
        entity.delete(&mut cx).await
    };
    match res {
        Ok(()) => match tx.commit().await {
            Ok(()) => status_only(StatusCode::NO_CONTENT),
            Err(_) => status_only(StatusCode::NOT_FOUND),
        },
        Err(_) => {
            let _ = tx.rollback().await;
            status_only(StatusCode::NOT_FOUND)
        }
    }
}

/// `GET /rest/users/{id}/userGroups`: the groups of an existing user, filtered by READ.
pub async fn user_groups(pool: &PgPool, p: &Principal, user_id: i32) -> Response {
    let mut tx = match begin(pool).await {
        Ok(t) => t,
        Err(r) => return r,
    };
    let users = match User::load_by_ids(&mut tx, &[user_id]).await {
        Ok(u) => u,
        Err(_) => return server_error(),
    };
    let Some(user) = users.into_iter().next() else {
        return status_only(StatusCode::NOT_FOUND);
    };
    let group_ids = groups_of(&user);
    let groups = match UserGroup::load_by_ids(&mut tx, &group_ids).await {
        Ok(g) => g,
        Err(_) => return server_error(),
    };
    let ids: Vec<i32> = groups.iter().filter_map(|g| g.id).collect();
    let ok = match allowed_ids(&mut tx, p, Ent::Group, &ids, Perm::Read).await {
        Ok(s) => s,
        Err(_) => return server_error(),
    };
    let visible: Vec<&UserGroup> = groups.iter().filter(|g| g.id.map(|i| ok.contains(&i)).unwrap_or(false)).collect();
    let _ = tx.rollback().await;
    json_response(StatusCode::OK, &visible)
}

/// `GET /rest/groups/{id}/users`: the members of an existing group, filtered by READ.
pub async fn group_users(pool: &PgPool, p: &Principal, group_id: i32) -> Response {
    let mut tx = match begin(pool).await {
        Ok(t) => t,
        Err(r) => return r,
    };
    let groups = match UserGroup::load_by_ids(&mut tx, &[group_id]).await {
        Ok(g) => g,
        Err(_) => return server_error(),
    };
    let Some(group) = groups.into_iter().next() else {
        return status_only(StatusCode::NOT_FOUND);
    };
    let members: Vec<User> = group.members.unwrap_or_default();
    let ids: Vec<i32> = members.iter().filter_map(|u| u.id).collect();
    let ok = match allowed_ids(&mut tx, p, Ent::User, &ids, Perm::Read).await {
        Ok(s) => s,
        Err(_) => return server_error(),
    };
    let visible: Vec<&User> = members.iter().filter(|u| u.id.map(|i| ok.contains(&i)).unwrap_or(false)).collect();
    let _ = tx.rollback().await;
    json_response(StatusCode::OK, &visible)
}

