//! HTTP Basic authentication against the `users` table, as
//! `ShogunCoreAuthenticationProvider` does it, and the authorities of the user.

use axum::http::HeaderValue;
use base64::Engine;
use sqlx::{PgPool, Row};

use crate::acl::Principal;

const ROLE_ADMIN: &str = "ROLE_ADMIN";
const ROLE_USER: &str = "ROLE_USER";

/// `BCryptPasswordEncoder.matches`: a value that does not look like a bcrypt
/// hash never matches.
fn bcrypt_matches(raw: &str, stored: &str) -> bool {
    static PATTERN: std::sync::OnceLock<regex::Regex> = std::sync::OnceLock::new();
    let re = PATTERN.get_or_init(|| regex::Regex::new(r"^\$2([ayb])?\$[0-9]{2}\$[./0-9A-Za-z]{53}").unwrap());
    if !re.is_match(stored) {
        return false;
    }
    bcrypt::verify(raw, stored).unwrap_or(false)
}

/// Returns the principal, `Ok(None)` when the credentials are missing, wrong,
/// the user is inactive or has no authorities (all of these are 401 in the original).
pub async fn authenticate(pool: &PgPool, header: Option<&HeaderValue>) -> Result<Option<Principal>, sqlx::Error> {
    let Some(h) = header.and_then(|h| h.to_str().ok()) else {
        return Ok(None);
    };
    let lower = h.to_ascii_lowercase();
    if !lower.starts_with("basic ") {
        return Ok(None);
    }
    let Ok(decoded) = base64::engine::general_purpose::STANDARD.decode(h[6..].trim()) else {
        return Ok(None);
    };
    let Ok(text) = String::from_utf8(decoded) else {
        return Ok(None);
    };
    let Some((account, raw_pw)) = text.split_once(':') else {
        return Ok(None);
    };

    let row = sqlx::query("SELECT id, active, password FROM users WHERE accountname = $1")
        .bind(account)
        .fetch_optional(pool)
        .await?;
    let Some(row) = row else { return Ok(None) };
    let id: i32 = row.try_get("id")?;
    let active: bool = row.try_get("active")?;
    let stored: Option<String> = row.try_get("password")?;
    if !active {
        return Ok(None);
    }
    let Some(stored) = stored else { return Ok(None) };
    if !bcrypt_matches(raw_pw, &stored) {
        return Ok(None);
    }

    // authorities: roles of the user and of the user's groups
    let roles: Vec<String> = sqlx::query_scalar(
        "SELECT r.name FROM users_roles ur JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1 \
         UNION \
         SELECT r.name FROM user_usergroup ug JOIN usergroups_roles gr ON gr.usergroup_id = ug.usergroup_id \
         JOIN roles r ON r.id = gr.role_id WHERE ug.user_id = $1",
    )
    .bind(id)
    .fetch_all(pool)
    .await?;
    let roles: Vec<String> = roles.into_iter().flatten().collect();
    if roles.is_empty() {
        return Ok(None);
    }
    let super_admin = roles.iter().any(|r| r == ROLE_ADMIN);
    let has_user = super_admin || roles.iter().any(|r| r == ROLE_USER);
    Ok(Some(Principal {
        id,
        account_name: account.to_string(),
        super_admin,
        has_user,
    }))
}
