//! Request dispatch: security (HTTP Basic, role gates), URL mapping, the
//! Accept check and the path-variable conversion, in the order Spring MVC
//! applies them.

use axum::body::Body;
use axum::extract::State;
use axum::http::{header, HeaderMap, Method, Request, StatusCode};
use axum::response::{IntoResponse, Response};
use sqlx::PgPool;

use crate::acl::Principal;
use crate::auth::authenticate;
use crate::handlers::{self, status_only};
use crate::model::layer::{Appearance, Layer};
use crate::model::source::Lds;
use crate::model::user::{Role, User, UserGroup};
use crate::res::parse_query;

#[derive(Clone)]
pub struct AppState {
    pub pool: PgPool,
}

/// The six resources of the slice, by their URL segment.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Res {
    Users,
    Groups,
    Roles,
    Layers,
    Lds,
    Appearances,
}

fn resource_of(seg: &str) -> Option<Res> {
    Some(match seg {
        "users" => Res::Users,
        "groups" => Res::Groups,
        "roles" => Res::Roles,
        "layers" => Res::Layers,
        "layerdatasources" => Res::Lds,
        "layerappearances" => Res::Appearances,
        _ => return None,
    })
}

/// Spring's `produces = application/json`: the Accept header must allow JSON.
fn accepts_json(headers: &HeaderMap) -> bool {
    match headers.get(header::ACCEPT) {
        None => true,
        Some(v) => match v.to_str() {
            Err(_) => false,
            Ok(s) => s.split(',').any(|t| {
                let m = t.split(';').next().unwrap_or("").trim().to_ascii_lowercase();
                m.is_empty() || m == "*/*" || m == "application/*" || m == "application/json"
            }),
        },
    }
}

fn unauthorized() -> Response {
    (
        StatusCode::UNAUTHORIZED,
        [(header::WWW_AUTHENTICATE, "Basic realm=\"SHOGun Realm\"")],
    )
        .into_response()
}

fn parse_id(seg: &str) -> Result<i32, Response> {
    seg.parse::<i32>().map_err(|_| status_only(StatusCode::BAD_REQUEST))
}

pub async fn handle(State(st): State<AppState>, req: Request<Body>) -> Response {
    let (parts, body) = req.into_parts();
    let path = parts.uri.path().to_string();
    let Some(rest) = path.strip_prefix("/rest") else {
        return status_only(StatusCode::NOT_FOUND);
    };
    if !(rest.is_empty() || rest.starts_with('/')) {
        return status_only(StatusCode::NOT_FOUND);
    }

    // security: every /rest/** request needs authenticated credentials
    let principal: Principal = match authenticate(&st.pool, parts.headers.get(header::AUTHORIZATION)).await {
        Ok(Some(p)) => p,
        Ok(None) => return unauthorized(),
        Err(_) => return status_only(StatusCode::INTERNAL_SERVER_ERROR),
    };

    let trimmed = rest.strip_suffix('/').unwrap_or(rest);
    let segs: Vec<&str> = trimmed.split('/').filter(|s| !s.is_empty()).collect();
    let resource = segs.first().and_then(|s| resource_of(s));

    // authorisation: the slice needs ROLE_USER, everything else ROLE_ADMIN
    match resource {
        Some(_) => {
            if !principal.has_user {
                return status_only(StatusCode::FORBIDDEN);
            }
        }
        None => {
            if !principal.super_admin {
                return status_only(StatusCode::FORBIDDEN);
            }
        }
    }
    let Some(resource) = resource else {
        return status_only(StatusCode::NOT_FOUND);
    };

    let query = parse_query(parts.uri.query());
    let method = parts.method.clone();
    let pool = &st.pool;

    match segs.len() {
        1 => match method {
            Method::GET => {
                if !accepts_json(&parts.headers) {
                    return status_only(StatusCode::NOT_ACCEPTABLE);
                }
                dispatch_list(pool, &principal, resource, &query).await
            }
            Method::POST => {
                if !accepts_json(&parts.headers) {
                    return status_only(StatusCode::NOT_ACCEPTABLE);
                }
                let Ok(bytes) = axum::body::to_bytes(body, 64 * 1024 * 1024).await else {
                    return status_only(StatusCode::BAD_REQUEST);
                };
                dispatch_create(pool, &principal, resource, &bytes).await
            }
            _ => status_only(StatusCode::METHOD_NOT_ALLOWED),
        },
        2 => {
            let seg = segs[1];
            if seg == "filter" && method == Method::GET {
                if !accepts_json(&parts.headers) {
                    return status_only(StatusCode::NOT_ACCEPTABLE);
                }
                return dispatch_filter(pool, &principal, resource, &query).await;
            }
            // remaining mappings: /{id}
            match method {
                Method::GET | Method::PUT | Method::DELETE => {}
                Method::POST => return status_only(StatusCode::METHOD_NOT_ALLOWED),
                _ => return status_only(StatusCode::METHOD_NOT_ALLOWED),
            }
            if method != Method::DELETE && !accepts_json(&parts.headers) {
                return status_only(StatusCode::NOT_ACCEPTABLE);
            }
            let id = match parse_id(seg) {
                Ok(i) => i,
                Err(r) => return r,
            };
            match method {
                Method::GET => dispatch_get(pool, &principal, resource, id).await,
                Method::DELETE => dispatch_delete(pool, &principal, resource, id).await,
                _ => {
                    let Ok(bytes) = axum::body::to_bytes(body, 64 * 1024 * 1024).await else {
                        return status_only(StatusCode::BAD_REQUEST);
                    };
                    dispatch_update(pool, &principal, resource, id, &bytes).await
                }
            }
        }
        3 => {
            let sub = segs[2];
            let is_sub = matches!(
                (resource, sub),
                (Res::Users, "userGroups") | (Res::Groups, "users")
            );
            if !is_sub {
                return status_only(StatusCode::NOT_FOUND);
            }
            if method != Method::GET {
                return status_only(StatusCode::METHOD_NOT_ALLOWED);
            }
            if !accepts_json(&parts.headers) {
                return status_only(StatusCode::NOT_ACCEPTABLE);
            }
            let id = match parse_id(segs[1]) {
                Ok(i) => i,
                Err(r) => return r,
            };
            match resource {
                Res::Users => handlers::user_groups(pool, &principal, id).await,
                _ => handlers::group_users(pool, &principal, id).await,
            }
        }
        _ => status_only(StatusCode::NOT_FOUND),
    }
}

