//! SHOGun REST slice: a Rust service with the URLs, status codes, JSON and
//! database behaviour of the Java SHOGun-Core REST controllers.

mod acl;
mod auth;
mod db;
mod handlers;
mod http;
mod jv;
mod model;
mod res;

use std::time::Duration;

use axum::routing::any;
use axum::Router;
use sqlx::postgres::PgPoolOptions;

use http::AppState;

#[tokio::main]
async fn main() {
    let database_url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(8080);

    // the database may still be starting: retry for a while
    let started = std::time::Instant::now();
    let pool = loop {
        match PgPoolOptions::new()
            .max_connections(16)
            .acquire_timeout(Duration::from_secs(10))
            .connect(&database_url)
            .await
        {
            Ok(p) => break p,
            Err(e) => {
                if started.elapsed() > Duration::from_secs(50) {
                    panic!("cannot connect to the database: {}", e);
                }
                eprintln!("waiting for the database: {}", e);
                tokio::time::sleep(Duration::from_secs(1)).await;
            }
        }
    };

    let app = Router::new()
        .fallback(any(http::handle))
        .with_state(AppState { pool });

    let listener = tokio::net::TcpListener::bind(("0.0.0.0", port))
        .await
        .expect("cannot bind the port");
    axum::serve(listener, app).await.expect("server error");
}
