#!/usr/bin/env python3
"""Runs scenarios against the Java reference (:8081, db ref) and the Rust port (:8090, db port).

Each scenario starts from the same seeded state in both databases, sends the same
requests, and compares: status codes, JSON bodies (order-insensitive) and the rows
of the slice tables afterwards.
"""
import base64
import json
import subprocess
import sys
import urllib.error
import urllib.request

REF = "http://localhost:8081/rest"
PORT = "http://localhost:8090/rest"
SLICE_TABLES = [
    "persons", "users", "roles", "usergroups", "user_usergroup", "users_roles", "usergroups_roles",
    "layers", "layerdatasources", "imagewmslayerdatasources", "tilewmslayerdatasources",
    "wfslayerdatasources", "wmtslayerdatasources", "wmtslayerdatasources_urls", "xyzlayerdatasources",
    "xyzlayerdatasrc_resolution", "layerappearances", "layerappearances_properties", "extents",
    "tilegrids", "tilegrid_resolution", "wmtstilegrids", "wmtstilegrids_matrixids",
    "userpermissions", "grouppermissions", "permissioncollections", "permissioncollections_permissions",
    "maps_layers", "hibernate_sequences",
]
TIME_COLS = {"created", "modified"}
PASSWORDS = {"admin": "shogun", "user": "shogun"}


def sh(cmd, check=True):
    return subprocess.run(cmd, shell=True, check=check, capture_output=True, text=True).stdout


def reset(db, dump):
    subprocess.run(
        f"pg_restore --clean --if-exists --no-owner --no-privileges -d {db} {dump} >/dev/null 2>&1 || true",
        shell=True, check=False)


def run_sql(db, sql):
    p = subprocess.run(["psql", "-d", db, "-q", "-v", "ON_ERROR_STOP=1", "-c", sql],
                       capture_output=True, text=True)
    if p.returncode != 0:
        raise RuntimeError(f"setup sql failed on {db}: {p.stderr}")


def columns(db, table):
    out = sh(f"psql -d {db} -Atc \"select column_name from information_schema.columns "
             f"where table_schema='public' and table_name='{table}' order by ordinal_position\"")
    return [c for c in out.split() if c not in TIME_COLS]


def snapshot(db):
    snap = {}
    for t in SLICE_TABLES:
        cols = columns(db, t)
        if not cols:
            snap[t] = None
            continue
        sel = ", ".join(f'"{c}"' for c in cols)
        out = sh(f"psql -d {db} -Atc \"select row_to_json(x)::text from (select {sel} from {t}) x\"")
        snap[t] = sorted(line for line in out.splitlines() if line.strip())
    return snap


def canon(v):
    if isinstance(v, list):
        items = [canon(x) for x in v]
        return sorted(items, key=lambda x: json.dumps(x, sort_keys=True))
    if isinstance(v, dict):
        return {k: canon(x) for k, x in v.items()}
    return v


def request(base, method, path, user, body, headers=None):
    url = base + path
    data = None
