fn java_hash(s: &str) -> i32 {
    let mut h: i32 = 0;
    for u in s.encode_utf16() {
        h = h.wrapping_mul(31).wrapping_add(u as i32);
    }
    h
}

/// Position of a key in the iteration order of the `HashMap` that holds the request
/// parameters (Jetty's parameter map): bucket index, then insertion order.
fn java_map_order(keys: &[String]) -> Vec<usize> {
    let mut cap: usize = 16;
    while keys.len() > cap * 3 / 4 {
        cap *= 2;
    }
    let mut idx: Vec<(usize, usize)> = keys
        .iter()
        .enumerate()
        .map(|(i, k)| {
            let h = java_hash(k) as u32;
            let spread = h ^ (h >> 16);
            ((spread as usize) & (cap - 1), i)
        })
        .collect();
    idx.sort();
    idx.into_iter().map(|(_, i)| i).collect()
}

/// `AbstractCrudService.findBySimpleFilter`: the valid filter fields with their
/// converted values. Empty when no valid field is named (the result is then empty).
/// Only one key per field is used (the first matching key in the parameter map's order).
pub fn filter_criteria<T: Res>(q: &[(String, String)]) -> Vec<(&'static str, Vec<FVal>)> {
    // distinct keys in first-occurrence order
    let mut keys: Vec<String> = Vec::new();
    for (k, _) in q {
        if !keys.contains(k) {
            keys.push(k.clone());
        }
    }
    let order = java_map_order(&keys);
    let mut out: Vec<(&'static str, Vec<FVal>)> = Vec::new();
    for (field, ft) in T::FIELDS {
        let chosen = order.iter().map(|&i| &keys[i]).find(|k| {
            !k.eq_ignore_ascii_case("output:only") && k.eq_ignore_ascii_case(field)
        });
        let Some(key) = chosen else {
            continue;
        };
        let vals: Vec<FVal> = q
            .iter()
            .filter(|(k, _)| k == key)
            .map(|(_, v)| FVal::convert(v, *ft))
            .collect();
        out.push((field, vals));
    }
    out
}

